1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	//! Fixed-size IPC message.
4	//!
5	//! The 104-byte layout matches MINIX 3's `sizeof(message) == 104` assertion
6	//! for `__x86_64__` (see `include/minix/ipc.h`). Both x86_64 and aarch64 ports
7	//! of minix.rs adopt the same size so that the message is ABI-portable.
8	//!
9	//! Note: MINIX 3 only ever shipped as a 32-bit OS (i386, and 32-bit ARM). The
10	//! `__x86_64__` layout we anchor on exists in the MINIX 3 source tree, but a
11	//! working 64-bit MINIX 3 was never an upstream release — it was a personal
12	//! prototype by this project's author. We treat the 104-byte layout as an ABI
13	//! *reference*, not a shipped 64-bit MINIX 3.
14	//!
15	//! The struct is explicitly 8-aligned. MINIX 3's `message` is a union over
16	//! sub-structs containing `uint64_t` fields, so its native alignment is 8.
17	//! minix.rs expresses `payload` as `[u8; 96]` for now, but future typed
18	//! accessor structs (slice 2.5) will overlay payload regions that contain
19	//! `u64` fields. Forcing the message itself to 8-align guarantees those
20	//! overlays are 8-aligned relative to the message base — required for
21	//! strict-alignment loads on aarch64.
22	//!
23	//! Typed access — MINIX 3 had a union over many `mess_*` payload variants
24	//! (`m1i1`, `m2l1`, etc.). minix.rs will eventually expose strongly-typed
25	//! accessor structs per call (e.g., `as_vfs_read()`), but those live in the
26	//! servers/userland crates so the kernel doesn't pull in every protocol
27	//! definition. For now, `payload` is a raw byte array that callers
28	//! interpret per-call.
29	
30	use crate::endpoint::Endpoint;
31	
32	/// 104-byte fixed-size IPC message. Layout matches MINIX 3 x86_64.
33	#[repr(C, align(8))]
34	#[derive(Copy, Clone, Debug)]
35	pub struct Message {
36	    /// Endpoint of the sender (set by the kernel on delivery).
37	    pub m_source: Endpoint,
38	    /// Call number on send; result code on reply.
39	    pub m_type: i32,
40	    /// Raw payload — interpreted per-call by typed accessors.
41	    pub payload: [u8; 96],
42	}
43	
44	// Compile-time guarantee that the layout matches MINIX 3's x86_64 message.
45	const _: () = assert!(core::mem::size_of::<Message>() == 104);
46	const _: () = assert!(core::mem::align_of::<Message>() == 8);
47	
48	/// One past the highest user VA reachable through TTBR0. Limine programs
49	/// `TCR_EL1.T0SZ = 16`, giving a 48-bit user VA space (`[0, 2^48)`); the
50	/// kernel's HHDM lives in the very high half via TTBR1 and is unreachable
51	/// from this range.
52	pub const USER_VA_TOP: u64 = 1 << 48;
53	
54	/// Bounds check for a user pointer of length `len` starting at `va`.
55	///
56	/// Rejects:
57	///   - NULL or sub-alignment-of-[`Message`] addresses (a NULL pointer or an
58	///     unaligned `read_volatile` is UB even before the access faults).
59	///   - Pointers whose range extends past [`USER_VA_TOP`].
60	///
61	/// A pure predicate over the message ABI shape, so it lives here (and is
62	/// host-testable) rather than in the kernel's copy helpers.
63	#[inline]
64	pub fn user_va_ok(va: u64, len: usize) -> bool {
65	    if va < core::mem::align_of::<Message>() as u64 {
66	        return false;
67	    }
68	    if !va.is_multiple_of(core::mem::align_of::<Message>() as u64) {
69	        return false;
70	    }
71	    match va.checked_add(len as u64) {
72	        Some(end) => end <= USER_VA_TOP,
73	        None => false,
74	    }
75	}
76	
77	/// User page granule — the 4 KiB stage-1 granule the kernel's page-table
78	/// walker uses. Declared here (rather than pulled from the kernel's `mmu`
79	/// module) so [`page_chunks`] stays a pure, host-testable helper.
80	pub const USER_PAGE_SIZE: u64 = 4096;
81	
82	/// One page-bounded slice of a user buffer, produced by [`page_chunks`].
83	#[derive(Copy, Clone, Debug, PartialEq, Eq)]
84	pub struct PageChunk {
85	    /// Page-aligned base VA of the page holding this chunk.
86	    pub page_va: u64,
87	    /// Byte offset of the chunk within that page.
88	    pub offset: usize,
89	    /// Chunk length. Never crosses the page end, never zero.
90	    pub len: usize,
91	}
92	
93	/// Split the user range `[va, va + len)` into ascending per-page chunks.
94	///
95	/// The kernel's cross-address-space copy engine walks one page-table leaf per
96	/// chunk, so it needs the range decomposed at page boundaries. A 104-byte
97	/// [`Message`] is only 8-aligned, so it genuinely can straddle two pages —
98	/// this is the arithmetic that gets that right.
99	///
100	/// A pure geometry helper over the message ABI shape, so it lives here (and is
101	/// host-testable) rather than in the kernel's copy helpers, alongside
102	/// [`user_va_ok`]. Yields nothing for `len == 0`.
103	#[inline]
104	pub fn page_chunks(va: u64, len: usize) -> PageChunks {
105	    PageChunks { va, remaining: len }
106	}
107	
108	/// Iterator returned by [`page_chunks`].
109	#[derive(Copy, Clone, Debug)]
110	pub struct PageChunks {
111	    va: u64,
112	    remaining: usize,
113	}
114	
115	impl Iterator for PageChunks {
116	    type Item = PageChunk;
117	
118	    fn next(&mut self) -> Option<PageChunk> {
119	        if self.remaining == 0 {
120	            return None;
121	        }
122	        let page_va = self.va & !(USER_PAGE_SIZE - 1);
123	        let offset = (self.va - page_va) as usize;
124	        let to_page_end = USER_PAGE_SIZE as usize - offset;
125	        let len = if to_page_end < self.remaining {
126	            to_page_end
127	        } else {
128	            self.remaining
129	        };
130	        self.va += len as u64;
131	        self.remaining -= len;
132	        Some(PageChunk {
133	            page_va,
134	            offset,
135	            len,
136	        })
137	    }
138	}
139	
140	#[cfg(test)]
141	mod tests {
142	    use super::*;
143	
144	    const MSG: usize = core::mem::size_of::<Message>();
145	    const PAGE: u64 = USER_PAGE_SIZE;
146	
147	    #[test]
148	    fn message_is_104_bytes() {
149	        assert_eq!(core::mem::size_of::<Message>(), 104);
150	    }
151	
152	    #[test]
153	    fn message_align_is_8() {
154	        assert_eq!(core::mem::align_of::<Message>(), 8);
155	    }
156	
157	    #[test]
158	    fn message_payload_offset_is_8() {
159	        let m = Message {
160	            m_source: 0,
161	            m_type: 0,
162	            payload: [0; 96],
163	        };
164	        let base = &m as *const _ as usize;
165	        let payload = m.payload.as_ptr() as usize;
166	        assert_eq!(payload - base, 8);
167	    }
168	
169	    #[test]
170	    fn user_va_ok_rejects_null() {
171	        assert!(!user_va_ok(0, core::mem::size_of::<Message>()));
172	    }
173	
174	    #[test]
175	    fn user_va_ok_rejects_unaligned() {
176	        assert!(!user_va_ok(0x10001, core::mem::size_of::<Message>()));
177	    }
178	
179	    #[test]
180	    fn user_va_ok_rejects_at_top() {
181	        assert!(!user_va_ok(USER_VA_TOP, core::mem::size_of::<Message>()));
182	    }
183	
184	    #[test]
185	    fn user_va_ok_rejects_overflow() {
186	        assert!(!user_va_ok(u64::MAX - 7, core::mem::size_of::<Message>()));
187	    }
188	
189	    #[test]
190	    fn user_va_ok_accepts_aligned_in_range() {
191	        // 8 MiB — where the boot stubs' stacks live.
192	        assert!(user_va_ok(0x80_0000, core::mem::size_of::<Message>()));
193	    }
194	
195	    #[test]
196	    fn page_chunks_empty_for_zero_len() {
197	        assert_eq!(page_chunks(0x80_0000, 0).count(), 0);
198	    }
199	
200	    /// Collect at most `N` chunks into a fixed array — `kernel-shared` is
201	    /// unconditionally `no_std`, so tests cannot use `Vec`.
202	    fn collect_chunks<const N: usize>(va: u64, len: usize) -> ([PageChunk; N], usize) {
203	        let empty = PageChunk {
204	            page_va: 0,
205	            offset: 0,
206	            len: 0,
207	        };
208	        let mut out = [empty; N];
209	        let mut n = 0;
210	        for c in page_chunks(va, len) {
211	            assert!(n < N, "more chunks than the test expected");
212	            out[n] = c;
213	            n += 1;
214	        }
215	        (out, n)
216	    }
217	
218	    #[test]
219	    fn page_chunks_single_chunk_when_page_aligned() {
220	        let (c, n) = collect_chunks::<2>(0x80_0000, MSG);
221	        assert_eq!(n, 1);
222	        assert_eq!(
223	            c[0],
224	            PageChunk {
225	                page_va: 0x80_0000,
226	                offset: 0,
227	                len: MSG,
228	            }
229	        );
230	    }
231	
232	    #[test]
233	    fn page_chunks_straddles_a_page_boundary() {
234	        // 8 bytes in the first page, the remaining 96 in the next — the
235	        // layout stub A's deliberate straddle probe produces.
236	        let va = 0x80_0000 + PAGE - 8;
237	        let (c, n) = collect_chunks::<3>(va, MSG);
238	        assert_eq!(n, 2);
239	        assert_eq!(
240	            c[0],
241	            PageChunk {
242	                page_va: 0x80_0000,
243	                offset: (PAGE - 8) as usize,
244	                len: 8,
245	            }
246	        );
247	        assert_eq!(
248	            c[1],
249	            PageChunk {
250	                page_va: 0x80_0000 + PAGE,
251	                offset: 0,
252	                len: MSG - 8,
253	            }
254	        );
255	    }
256	
257	    #[test]
258	    fn page_chunks_exactly_fills_the_page_tail() {
259	        let va = 0x80_0000 + PAGE - MSG as u64;
260	        let (c, n) = collect_chunks::<2>(va, MSG);
261	        assert_eq!(n, 1);
262	        assert_eq!(c[0].offset + c[0].len, PAGE as usize);
263	    }
264	
265	    #[test]
266	    fn page_chunks_spans_three_pages() {
267	        // Start mid-page, run past two full pages: partial, full, partial.
268	        let va = 0x80_0000 + 0x800;
269	        let len = (2 * PAGE) as usize;
270	        let (c, n) = collect_chunks::<4>(va, len);
271	        assert_eq!(n, 3);
272	        assert_eq!(c[0].len, 0x800);
273	        assert_eq!(c[1].len, PAGE as usize);
274	        assert_eq!(c[1].offset, 0);
275	        assert_eq!(c[2].len, 0x800);
276	        assert_eq!(c[2].offset, 0);
277	    }
278	
279	    #[test]
280	    fn page_chunks_are_contiguous_and_total_len() {
281	        let va = 0x80_0000 + 0x123 * 8;
282	        let len = 3 * PAGE as usize + 17;
283	        let mut next_va = va;
284	        let mut total = 0usize;
285	        for c in page_chunks(va, len) {
286	            assert!(c.len > 0);
287	            assert_eq!(c.page_va % PAGE, 0);
288	            assert_eq!(c.page_va + c.offset as u64, next_va);
289	            assert!(c.offset + c.len <= PAGE as usize);
290	            next_va += c.len as u64;
291	            total += c.len;
292	        }
293	        assert_eq!(total, len);
294	        assert_eq!(next_va, va + len as u64);
295	    }
296	}
