1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	//! Kernel-call dispatch — the `SYSTEM` task's role.
4	//!
5	//! In MINIX 3, `SYSTEM` is a kernel pseudo-task: it has a proc-table slot but
6	//! no scheduler context. When a server `SENDREC`s the `SYSTEM` endpoint, the
7	//! IPC fast path in `proc.c::do_ipc` short-circuits into `kernel_call()`
8	//! (`kernel/system.c`), which runs synchronously in the *caller's* EL1 stack
9	//! and writes the reply back into the caller's user buffer. The caller never
10	//! actually blocks on a receiver; SYSTEM's `IMAGE` entry exists only so that
11	//! the endpoint encodes to a valid `ProcNr`.
12	//!
13	//! minix.rs inherits exactly that shape. [`ipc::dispatch`] detects
14	//! `src_dst_e == boot_endpoint(SYSTEM)` in the SENDREC arm and diverts here
15	//! instead of calling [`ipc::send::mini_send`]; the rest of the IPC engine is
16	//! untouched.
17	//!
18	//! [`ipc::dispatch`]: crate::ipc
19	//! [`ipc::send::mini_send`]: crate::ipc
20	
21	mod do_diagctl;
22	mod do_exec;
23	mod do_exit;
24	mod do_fork;
25	mod do_getinfo;
26	mod do_privctl;
27	mod do_schedule;
28	mod do_setalarm;
29	mod do_sig;
30	mod do_vmctl;
31	mod stubs;
32	
33	use core::fmt::Write;
34	use core::sync::atomic::{AtomicU64, Ordering};
35	
36	use minixrs_kernel_shared::ProcNr;
37	use minixrs_kernel_shared::callnr::{
38	    KERNEL_CALL, NR_KERN_CALLS, NR_SYS_CALLS, SYS_COPY, SYS_DIAGCTL, SYS_ENDKSIG, SYS_EXEC,
39	    SYS_EXIT, SYS_FORK, SYS_GETINFO, SYS_GETKSIG, SYS_IRQCTL, SYS_KILL, SYS_PRIVCTL, SYS_SAFECOPY,
40	    SYS_SCHEDCTL, SYS_SCHEDULE, SYS_SETALARM, SYS_SETGRANT, SYS_TIMES, SYS_VMCTL,
41	};
42	use minixrs_kernel_shared::com::{NR_SYS_PROCS, SYSTEM, boot_endpoint};
43	use minixrs_kernel_shared::endpoint::Endpoint;
44	use minixrs_kernel_shared::error::{EBADREQUEST, ECALLDENIED, OK};
45	use minixrs_kernel_shared::message::Message;
46	
47	use crate::ipc::{copy_msg_from_user, copy_msg_to_user};
48	use crate::proc::bitmap::{get_call_bit, get_sys_bit};
49	use crate::proc::table::{N_PROC_SLOTS, okendpt, proc_index};
50	use crate::proc::{Priv, Proc};
51	use crate::uart::Uart;
52	
53	/// Boot-time endpoint of the `SYSTEM` kernel task. Generation never bumps for
54	/// kernel tasks in Phase 2 — they are statically slotted at boot and never
55	/// exit — so this single constant identifies SYSTEM for the entire kernel
56	/// lifetime.
57	#[inline]
58	pub fn system_endpoint() -> Endpoint {
59	    boot_endpoint(SYSTEM)
60	}
61	
62	/// Resolve a kernel-call target endpoint to a proc-table index. `SELF` maps
63	/// to the caller; anything else must pass [`okendpt`] — slots recycle as of
64	/// slice 4.6, so a stale endpoint returns `EDEADSRCDST` rather than resolving
65	/// to the slot's new occupant. Shared by every target-taking handler.
66	fn resolve_target(
67	    proc_table: &[Proc; N_PROC_SLOTS],
68	    caller_nr: ProcNr,
69	    target_e: Endpoint,
70	) -> Result<usize, i32> {
71	    if target_e == minixrs_kernel_shared::endpoint::SELF {
72	        proc_index(caller_nr).ok_or(minixrs_kernel_shared::error::EINVAL)
73	    } else {
74	        okendpt(proc_table, target_e)
75	    }
76	}
77	
78	/// Cadence of the boot-time kernel-call trace. Mirrors `ipc::TRACE_EVERY`.
79	const KCALL_TRACE_EVERY: u64 = 100;
80	/// Running total of kernel calls dispatched, sampled by the trace.
81	static CALL_COUNT: AtomicU64 = AtomicU64::new(0);
82	
83	/// `SENDREC`-to-SYSTEM fast path.
84	///
85	/// Reads the request out of `user_msg_va`, runs the dispatcher, and writes
86	/// the reply (m_source = SYSTEM, m_type = result, possibly mutated payload)
87	/// back to the same buffer. The caller stays runnable and `el1_svc_tail`
88	/// resumes it on return.
89	///
90	/// Returns the IPC-layer result (`OK`, `EFAULT`, `ECALLDENIED`); the
91	/// kernel-call result code is carried in the reply's `m_type` field.
92	pub fn kernel_call_sendrec(
93	    proc_table: &mut [Proc; N_PROC_SLOTS],
94	    priv_table: &mut [Priv; NR_SYS_PROCS],
95	    caller_nr: ProcNr,
96	    user_msg_va: u64,
97	) -> i32 {
98	    // Kernel invariants: any proc that reached the SVC handler has a slot
99	    // and a priv_id installed (proc::init or userland_bootstrap), and
100	    // SYSTEM is populated by proc::init. A None here is a structural bug
101	    // in those bootstrap paths, not a user-recoverable error — panic at
102	    // the call site rather than mask it behind ECALLDENIED.
103	    let caller_idx = proc_index(caller_nr).expect("caller in proc table");
104	    let caller_priv_id = proc_table[caller_idx]
105	        .priv_id
106	        .expect("caller priv populated");
107	    let system_idx = proc_index(SYSTEM).expect("SYSTEM in proc table");
108	    let system_priv_id = proc_table[system_idx]
109	        .priv_id
110	        .expect("SYSTEM priv populated by proc::init");
111	
112	    // Apply the same ipc_to permission check that `mini_send` does
113	    // (`ipc/send.rs:59`) — the SYSTEM endpoint isn't a special trust
114	    // boundary, just a routing shortcut, so a caller without SYSTEM in its
115	    // ipc_to bitmap must still be denied here.
116	    if !get_sys_bit(
117	        &priv_table[caller_priv_id.as_usize()].ipc_to,
118	        system_priv_id,
119	    ) {
120	        return ECALLDENIED;
121	    }
122	
123	    let caller_ttbr0 = proc_table[caller_idx].ttbr0_pa;
124	    let mut msg = match copy_msg_from_user(caller_ttbr0, user_msg_va) {
125	        Ok(m) => m,
126	        Err(e) => return e,
127	    };
128	    let original_m_type = msg.m_type;
129	
130	    // Stamp m_source so handlers see the verified caller endpoint rather
131	    // than whatever the user scribbled into the request.
132	    msg.m_source = proc_table[caller_idx].endpoint;
133	
134	    // Dispatch. Most handlers want a single caller slot, but `do_vmctl`
135	    // operates on a *target* proc named in the message, so it needs the whole
136	    // table — pass the full slices and let the dispatcher hand each handler
137	    // what it needs.
138	    let result = kernel_call_dispatch(proc_table, priv_table, caller_nr, &mut msg);
139	
140	    // Build the reply.
141	    //
142	    // An EFAULT here means the kernel call *already ran* and its side effects
143	    // are committed — the caller just cannot be told what happened, and sees
144	    // EFAULT in x0 instead of the reply. Its buffer is left untouched
145	    // (`copy_msg_to_user` is all-or-nothing), so it never observes a partial
146	    // reply. This is the MINIX shape; before slice 5.1 the case was
147	    // unreachable because a bad reply buffer panicked instead.
148	    //
149	    // The target address space is re-read rather than reused from the request
150	    // copy: `SYS_EXEC` swaps its target's `(ttbr0_pa, asid)`, and a caller that
151	    // exec'd *itself* would otherwise get its reply written into the address
152	    // space that was just torn down. (`do_exec` rejects a self-target today,
153	    // so this is defence in depth, not a live bug.)
154	    msg.m_source = system_endpoint();
155	    msg.m_type = result;
156	    let reply_ttbr0 = proc_table[caller_idx].ttbr0_pa;
157	    if let Err(e) = copy_msg_to_user(reply_ttbr0, user_msg_va, &msg) {
158	        return e;
159	    }
160	
161	    let n = CALL_COUNT.fetch_add(1, Ordering::Relaxed) + 1;
162	    if n.is_multiple_of(KCALL_TRACE_EVERY) {
163	        let call_idx = original_m_type - KERNEL_CALL;
164	        let mut uart = Uart::new();
165	        let _ = writeln!(
166	            uart,
167	            "[ksys {n}] caller={caller_nr} call={call_idx} result={result}",
168	        );
169	    }
170	
171	    OK
172	}
173	
174	/// Per-call dispatcher.
175	///
176	/// Steps: range-check `m_type - KERNEL_CALL`, gate against
177	/// `Priv::k_call_mask`, then route to the handler. Returns the result code
178	/// that becomes the reply's `m_type`.
179	///
180	/// `SYS_VMCTL` / `SYS_SCHEDULE` / `SYS_SCHEDCTL` and the slice-4.5 signal trio
181	/// (`SYS_KILL` / `SYS_GETKSIG` / `SYS_ENDKSIG`) act on a *target* proc named in
182	/// the message, so they take the whole `proc_table` + `caller_nr` (and
183	/// `do_kill` / `do_exit` additionally write `notify_pending` bitmaps, which is
184	/// why `priv_table` is `&mut`). Every other handler acts only on the caller,
185	/// so it gets a single caller slot re-borrowed inside its arm (see
186	/// [`dispatch_caller_local`]).
187	fn kernel_call_dispatch(
188	    proc_table: &mut [Proc; N_PROC_SLOTS],
189	    priv_table: &mut [Priv; NR_SYS_PROCS],
190	    caller_nr: ProcNr,
191	    msg: &mut Message,
192	) -> i32 {
193	    let caller_idx = proc_index(caller_nr).expect("caller in proc table");
194	    let caller_priv_id = proc_table[caller_idx]
195	        .priv_id
196	        .expect("caller priv populated");
197	
198	    let call_idx = msg.m_type - KERNEL_CALL;
199	    if call_idx < 0 || (call_idx as usize) >= NR_SYS_CALLS {
200	        return EBADREQUEST;
201	    }
202	    let call_idx = call_idx as usize;
203	
204	    if !get_call_bit(&priv_table[caller_priv_id.as_usize()].k_call_mask, call_idx) {
205	        return ECALLDENIED;
206	    }
207	
208	    // Calls that act on a *target* proc named in the message take the whole
209	    // table + caller_nr; route them before the caller-local dispatch.
210	    match msg.m_type {
211	        SYS_VMCTL => return do_vmctl::do_vmctl(proc_table, caller_nr, msg),
212	        SYS_SCHEDULE => return do_schedule::do_schedule(proc_table, caller_nr, msg),
213	        SYS_SCHEDCTL => return do_schedule::do_schedctl(proc_table, caller_nr, msg),
214	        SYS_KILL => return do_sig::do_kill(proc_table, priv_table, caller_nr, msg),
215	        SYS_GETKSIG => return do_sig::do_getksig(proc_table, caller_nr, msg),
216	        SYS_ENDKSIG => return do_sig::do_endksig(proc_table, caller_nr, msg),
217	        SYS_EXIT => return do_exit::do_exit(proc_table, priv_table, caller_nr, msg),
218	        SYS_FORK => return do_fork::do_fork(proc_table, caller_nr, msg),
219	        SYS_EXEC => return do_exec::do_exec(proc_table, caller_nr, msg),
220	        SYS_PRIVCTL => return do_privctl::do_privctl(proc_table, caller_nr, msg),
221	        _ => {}
222	    }
223	
224	    // proc_table and priv_table are disjoint statics, so borrowing one slot
225	    // in each is permitted.
226	    let caller = &mut proc_table[caller_idx];
227	    let caller_priv = &priv_table[caller_priv_id.as_usize()];
228	    dispatch_caller_local(caller, caller_priv, msg)
229	}
230	
231	/// Dispatch the caller-only kernel calls (everything except `SYS_VMCTL`).
232	///
233	/// The const assert locks the arm count — adding a new `SYS_*` without a new
234	/// arm here is a compile error.
235	fn dispatch_caller_local(caller: &mut Proc, caller_priv: &Priv, msg: &mut Message) -> i32 {
236	    const _: () = assert!(
237	        NR_KERN_CALLS == 18,
238	        "expand kernel_call_dispatch when a new SYS_* lands",
239	    );
240	    match msg.m_type {
241	        SYS_GETINFO => do_getinfo::do_getinfo(caller, caller_priv, msg),
242	        SYS_COPY => stubs::do_copy(caller, caller_priv, msg),
243	        SYS_SAFECOPY => stubs::do_safecopy(caller, caller_priv, msg),
244	        SYS_IRQCTL => stubs::do_irqctl(caller, caller_priv, msg),
245	        // SYS_VMCTL / SYS_SCHEDULE / SYS_SCHEDCTL / SYS_KILL / SYS_GETKSIG /
246	        // SYS_ENDKSIG / SYS_EXIT / SYS_FORK / SYS_EXEC / SYS_PRIVCTL are handled
247	        // in `kernel_call_dispatch` (they act on a target proc and need the table).
248	        SYS_SETALARM => do_setalarm::do_setalarm(caller, caller_priv, msg),
249	        SYS_TIMES => stubs::do_times(caller, caller_priv, msg),
250	        SYS_DIAGCTL => do_diagctl::do_diagctl(caller, caller_priv, msg),
251	        SYS_SETGRANT => stubs::do_setgrant(caller, caller_priv, msg),
252	        _ => EBADREQUEST,
253	    }
254	}
