3	//! `SYS_VMCTL` — kernel-mediated page-table control.
4	//!
5	//! minix.rs keeps every unsafe PTE write and the physical frame allocator in
6	//! the kernel; the user-space VM server (slice 3.4) drives paging *policy* by
7	//! issuing the subcalls implemented here. This mirrors MINIX 3's split of
8	//! mechanism (kernel) from policy (VM) while moving frame ownership kernel-side
9	//! (MINIX 3's VM owns physical memory directly).
10	//!
11	//! Each subcall names a *target* process by endpoint — slice 3.3 only ever
12	//! sees a process targeting itself (stub D pre-maps then frees its own heap),
13	//! but the cross-process shape is what 3.4's VM needs when it resolves another
14	//! process's fault. Resolution mirrors `ipc/send.rs`: `endpoint_proc` →
15	//! `proc_index`, with the `SELF` sentinel mapped to the caller.
16	//!
17	//! ## Trust model
18	//!
19	//! There is no *per-target* authorization here: any caller that reaches this
20	//! handler may name any process (a kernel task slot — negative `ProcNr` —
21	//! included) and mutate its page tables, fault state, and run-queue status.
22	//! The single gate is `Priv::k_call_mask` granting `SYS_VMCTL`, checked in
23	//! `kernel_call_dispatch` before we run. This is the deliberate MINIX 3
24	//! mechanism/policy split: `SYS_VMCTL` is privileged and the VM server (3.4)
25	//! is its sole intended holder — VM is trusted to target only processes it
26	//! legitimately manages, exactly as MINIX 3 trusts its VM. If a future slice
27	//! hands `SYS_VMCTL` to a less-trusted process, target authorization must be
28	//! added before that lands.
29	//!
30	//! ## Message payload layout (offsets within `Message::payload`)
31	//!
32	//! | offset  | field            | direction | subcalls                     |
33	//! |---------|------------------|-----------|------------------------------|
34	//! |  0..4   | subcall selector | in        | all                          |
35	//! |  4..8   | target endpoint  | in        | all (`SELF` = caller)        |
36	//! |  8..16  | `vaddr` (u64)    | in        | `PT_MAP`, `PT_UNMAP`         |
37	//! | 16..20  | prot bits (i32)  | in        | `PT_MAP`                     |
38	//! | 16..24  | `pa` (u64)       | out       | `PT_MAP` (allocated frame)   |
39	//! |  8..16  | fault addr (u64) | out       | `GET_PAGEFAULT`              |
40	//! | 16..20  | fault flags(u32) | out       | `GET_PAGEFAULT`              |
41	//! | 20..28  | fault ip (u64)   | out       | `GET_PAGEFAULT`              |
42	//!
43	//! Run-queue transitions (`CLEAR_PAGEFAULT`, `VMINHIBIT_*`) use the
44	//! `sched::rts_set`/`rts_unset` capture-then-borrow-end pattern that
45	//! `ipc::send::mini_send` established, so the `&mut Proc` borrow ends before
46	//! the internal `enqueue`/`dequeue` re-borrows the same slot.
47	
48	use core::fmt::Write;
49	use core::sync::atomic::{AtomicU64, Ordering};
50	
51	use minixrs_kernel_shared::ProcNr;
52	use minixrs_kernel_shared::callnr::{
53	    NR_VMCTL_SUBCALLS, VMCTL_CLEAR_PAGEFAULT, VMCTL_GET_PAGEFAULT, VMCTL_PROT_EXEC,
54	    VMCTL_PROT_WRITE, VMCTL_PT_MAP, VMCTL_PT_UNMAP, VMCTL_VMINHIBIT_CLEAR, VMCTL_VMINHIBIT_SET,
55	};
56	use minixrs_kernel_shared::endpoint::Endpoint;
57	use minixrs_kernel_shared::error::{EINVAL, ENOMEM, OK};
58	use minixrs_kernel_shared::message::Message;
59	
60	use crate::arch::aarch64::addrspace::{MapError, Prot, map_page_in, unmap_page_in};
61	use crate::arch::aarch64::mmu;
62	use crate::mm::{Frame, alloc_frame, free_frame};
63	use crate::proc::flags::{RTS_PAGEFAULT, RTS_VMINHIBIT};
64	use crate::proc::table::N_PROC_SLOTS;
65	use crate::proc::{PageFaultState, Proc, sched};
66	use crate::uart::Uart;
67	
68	/// How many `PT_MAP`/`PT_UNMAP` calls get a detailed head trace before steady
69	/// state falls back to the `[ksys N]` sampling in `kernel_call_sendrec`.
70	/// Stub D loops at kernel-call speed, so an unsampled per-call trace would
71	/// drown everything else (same reasoning as slice 2.6's `TRACE_HEAD`).
72	const VMCTL_TRACE_HEAD: u64 = 6;
73	static MAP_COUNT: AtomicU64 = AtomicU64::new(0);
74	static UNMAP_COUNT: AtomicU64 = AtomicU64::new(0);
75	
76	/// `SYS_VMCTL` entry point. Dispatches by subcall selector after resolving the
77	/// target process named in the payload.
78	pub(super) fn do_vmctl(
79	    proc_table: &mut [Proc; N_PROC_SLOTS],
80	    caller_nr: ProcNr,
81	    msg: &mut Message,
82	) -> i32 {
83	    let subcall = read_i32(msg, 0);
84	    let target_e: Endpoint = read_i32(msg, 4);
85	    // No per-target authorization — the caller is trusted via `k_call_mask`
86	    // (see the "Trust model" note above). `target_nr` may be any slot,
87	    // including a kernel task; `proc_index` only range-checks it.
88	    let target_idx = match super::resolve_target(proc_table, caller_nr, target_e) {
89	        Ok(idx) => idx,
90	        Err(e) => return e,
91	    };
92	
93	    // Lock subcall coverage: adding a `VMCTL_*` without a match arm is a
94	    // compile error.
95	    const _: () = assert!(
96	        NR_VMCTL_SUBCALLS == 6,
97	        "expand do_vmctl when a new VMCTL_* subcall lands",
98	    );
99	    match subcall {
100	        VMCTL_PT_MAP => pt_map(proc_table, target_idx, msg),
101	        VMCTL_PT_UNMAP => pt_unmap(proc_table, target_idx, msg),
102	        VMCTL_CLEAR_PAGEFAULT => clear_pagefault(proc_table, target_idx),
103	        VMCTL_GET_PAGEFAULT => get_pagefault(proc_table, target_idx, msg),
104	        VMCTL_VMINHIBIT_SET => set_vminhibit(proc_table, target_idx, true),
105	        VMCTL_VMINHIBIT_CLEAR => set_vminhibit(proc_table, target_idx, false),
106	        _ => EINVAL,
107	    }
108	}
109	
110	/// `VMCTL_PT_MAP` — allocate a fresh frame and map it into the target's AS.
111	///
112	/// The kernel allocates because it owns the frame allocator; the reply carries
113	/// the chosen PA so VM (3.4) can track the frame for later `PT_UNMAP`.
114	fn pt_map(proc_table: &mut [Proc; N_PROC_SLOTS], target_idx: usize, msg: &mut Message) -> i32 {
115	    let vaddr = read_u64(msg, 8);
116	    let prot_bits = read_i32(msg, 16);
117	    let prot = Prot {
118	        writable: prot_bits & VMCTL_PROT_WRITE != 0,
119	        executable: prot_bits & VMCTL_PROT_EXEC != 0,
120	    };
121	
122	    // Snapshot the target's AS coordinates, then drop the borrow before
123	    // touching the frame allocator / page tables (neither aliases the proc
124	    // table).
125	    let (ttbr0_pa, asid, name) = {
126	        let p = &proc_table[target_idx];
127	        (p.ttbr0_pa, p.asid, p.name[0])
128	    };
129	    if ttbr0_pa == 0 {
130	        return EINVAL; // target never runs at EL0 (kernel task / unset slot)
131	    }
132	
133	    let frame = match alloc_frame() {
134	        Some(f) => f,
135	        None => return ENOMEM,
136	    };
137	    match map_page_in(ttbr0_pa, vaddr, frame.addr(), prot) {
138	        Ok(()) => {}
139	        // Already-mapped or misaligned/out-of-range: hand the frame back and
140	        // report the error rather than leaking it.
141	        Err(MapError::AlreadyMapped) | Err(_) => {
142	            free_frame(frame);
143	            return EINVAL;
144	        }
145	    }
146	    // SAFETY: ASID-tagged TLBI. The target's TTBR0 may or may not be the live
147	    // one; ASID-tagged invalidation covers that ASID's entries either way.
148	    unsafe { mmu::flush_tlb_asid(asid) };
149	
150	    // Reply: the allocated PA (overwrites the prot-bits input word).
151	    write_u64(msg, 16, frame.addr());
152	
153	    let n = MAP_COUNT.fetch_add(1, Ordering::Relaxed) + 1;
154	    if n <= VMCTL_TRACE_HEAD {
155	        let mut uart = Uart::new();
156	        let _ = writeln!(
157	            uart,
158	            "[ksys VMCTL_PT_MAP] proc={} va={vaddr:#x} pa={:#x} result=0",
159	            name as char,
160	            frame.addr(),
161	        );
162	    }
163	    OK
164	}
165	
166	/// `VMCTL_PT_UNMAP` — clear the PTE at `vaddr` and free its backing frame.
167	///
168	/// Assumes the leaf is an anonymous, kernel-allocated frame (everything
169	/// `PT_MAP` installs is). Mapping a caller-supplied device/shared PA — which
170	/// must *not* be freed here — is a future subcall.
171	fn pt_unmap(proc_table: &mut [Proc; N_PROC_SLOTS], target_idx: usize, msg: &mut Message) -> i32 {
172	    let vaddr = read_u64(msg, 8);
173	    let (ttbr0_pa, asid, name) = {
174	        let p = &proc_table[target_idx];
175	        (p.ttbr0_pa, p.asid, p.name[0])
176	    };
177	    if ttbr0_pa == 0 {
178	        return EINVAL;
179	    }
180	
181	    let Some(pa) = unmap_page_in(ttbr0_pa, vaddr) else {
182	        return EINVAL; // nothing mapped at vaddr
183	    };
184	    free_frame(Frame::from_addr(pa));
185	    // SAFETY: ASID-tagged TLBI; same rationale as `pt_map`.
186	    unsafe { mmu::flush_tlb_asid(asid) };
187	
188	    let n = UNMAP_COUNT.fetch_add(1, Ordering::Relaxed) + 1;
189	    if n <= VMCTL_TRACE_HEAD {
190	        let mut uart = Uart::new();
191	        let _ = writeln!(
192	            uart,
193	            "[ksys VMCTL_PT_UNMAP] proc={} va={vaddr:#x} pa={pa:#x} result=0",
194	            name as char,
195	        );
196	    }
197	    OK
198	}
199	
200	/// `VMCTL_CLEAR_PAGEFAULT` — clear the target's recorded fault and unblock it.
201	fn clear_pagefault(proc_table: &mut [Proc; N_PROC_SLOTS], target_idx: usize) -> i32 {
202	    let p = &mut proc_table[target_idx];
203	    p.page_fault_state = PageFaultState::EMPTY;
204	    // SAFETY: rts_unset captures `nr` then ends the `p` borrow before enqueue;
205	    // single-threaded EL1 context (same invariant as `do_page_fault`).
206	    unsafe { sched::rts_unset(p, RTS_PAGEFAULT) };
207	    OK
208	}
209	
210	/// `VMCTL_GET_PAGEFAULT` — return the target's recorded fault state.
211	///
212	/// Only meaningful while the target is blocked on a page fault; reading it
213	/// otherwise would hand VM stale coordinates, so reject that case.
214	fn get_pagefault(
215	    proc_table: &mut [Proc; N_PROC_SLOTS],
216	    target_idx: usize,
217	    msg: &mut Message,
218	) -> i32 {
219	    let p = &proc_table[target_idx];
220	    if p.rts_flags.load(Ordering::Relaxed) & RTS_PAGEFAULT == 0 {
221	        return EINVAL;
222	    }
223	    let pf = p.page_fault_state;
224	    write_u64(msg, 8, pf.addr);
225	    write_i32(msg, 16, pf.flags as i32);
226	    write_u64(msg, 20, pf.ip);
227	    OK
228	}
229	
230	/// `VMCTL_VMINHIBIT_SET`/`_CLEAR` — gate scheduling of the target while VM
231	/// mutates its address space.
232	fn set_vminhibit(proc_table: &mut [Proc; N_PROC_SLOTS], target_idx: usize, set: bool) -> i32 {
233	    let p = &mut proc_table[target_idx];
234	    // SAFETY: rts_set/rts_unset capture `nr` then end the `p` borrow before
235	    // dequeue/enqueue; single-threaded EL1 context.
236	    unsafe {
237	        if set {
238	            sched::rts_set(p, RTS_VMINHIBIT);
239	        } else {
240	            sched::rts_unset(p, RTS_VMINHIBIT);
241	        }
242	    }
243	    OK
244	}
245	
246	// ----- payload accessors ----------------------------------------------------
247	
248	#[inline]
249	fn read_i32(msg: &Message, off: usize) -> i32 {
250	    i32::from_ne_bytes(
251	        msg.payload[off..off + 4]
252	            .try_into()
253	            .expect("payload in range"),
254	    )
255	}
256	
257	#[inline]
258	fn read_u64(msg: &Message, off: usize) -> u64 {
259	    u64::from_ne_bytes(
260	        msg.payload[off..off + 8]
261	            .try_into()
262	            .expect("payload in range"),
263	    )
264	}
265	
266	#[inline]
267	fn write_i32(msg: &mut Message, off: usize, v: i32) {
268	    msg.payload[off..off + 4].copy_from_slice(&v.to_ne_bytes());
269	}
270	
271	#[inline]
272	fn write_u64(msg: &mut Message, off: usize, v: u64) {
273	    msg.payload[off..off + 8].copy_from_slice(&v.to_ne_bytes());
274	}
