3	//! `SYS_DIAGCTL` — the servers' debug channel (slice 5.1, decision D2).
4	//!
5	//! Replaces the slice-2.6 `ENOSYS` placeholder. User-space servers run at EL0
6	//! with no console of their own; before this call the only way to observe them
7	//! was indirectly, through kernel-side `[ipc]` / `[ksys]` / `[pf]` traces. Every
8	//! remaining Phase 5 slice needs first-party server output while grants, TTY,
9	//! VFS and MFS are still being built, so the debug channel lands early.
10	//!
11	//! MINIX 3 (`kernel/system/do_diagctl.c`) passes a `(buf, len)` user pointer and
12	//! `data_copy`s the text in. minix.rs carries the text **inline in the message
13	//! payload** instead: the channel then needs no user-copy machinery, cannot
14	//! fault, and works even while the copy engine itself is under construction.
15	//! The cost is a per-call text budget of [`DIAG_TEXT_MAX`] bytes;
16	//! `server-rt::diag_print` splits longer strings across successive calls.
17	//!
18	//! This is a *caller-local* kernel call — it acts only on the caller — so it
19	//! takes a single `&mut Proc` and is dispatched through
20	//! [`dispatch_caller_local`](super::dispatch_caller_local), unlike the
21	//! target-taking `do_vmctl` / `do_schedule`.
22	//!
23	//! ## Message payload layout (offsets within `Message::payload`)
24	//!
25	//! | offset                              | field                        | direction |
26	//! |-------------------------------------|------------------------------|-----------|
27	//! | 0..4                                | subcode (i32), `DIAGCTL_CODE_*` | in     |
28	//! | 4..8                                | text length (i32)            | in        |
29	//! | `DIAG_TEXT_OFF..DIAG_TEXT_OFF+len`  | text bytes                   | in        |
30	//!
31	//! No reply payload; `m_type` is `OK` or `EINVAL`.
32	//!
33	//! ## Trust
34	//!
35	//! The `[diag <name>]` prefix is the caller's name **as the kernel knows it**
36	//! (`Proc::name`, set at load time), never anything from the payload — a server
37	//! can only ever identify itself, the same anti-spoof property DS relies on for
38	//! `m_source`. Text bytes are restricted to printable ASCII, so a caller cannot
39	//! inject newlines or escapes that would break the one-call-one-line framing
40	//! that `tests/qemu-boot.expected` greps against.
41	//!
42	//! No privilege gate beyond the usual one: `Priv::k_call_mask` already limits
43	//! kernel calls to server-grade privs, and the shared USER priv has an empty
44	//! mask, so ordinary user processes cannot reach this call at all.
45	
46	use core::fmt::Write;
47	
48	use minixrs_kernel_shared::callnr::{
49	    DIAG_TEXT_MAX, DIAG_TEXT_OFF, DIAGCTL_CODE_DIAG, DIAGCTL_CODE_REGISTER,
50	    DIAGCTL_CODE_STACKTRACE, DIAGCTL_CODE_UNREGISTER,
51	};
52	use minixrs_kernel_shared::error::{EINVAL, OK};
53	use minixrs_kernel_shared::message::Message;
54	
55	use crate::proc::{Priv, Proc};
56	use crate::uart::Uart;
57	
58	/// `SYS_DIAGCTL`. Prints one console line of caller-supplied text.
59	pub(super) fn do_diagctl(caller: &mut Proc, _caller_priv: &Priv, msg: &mut Message) -> i32 {
60	    match read_i32(msg, 0) {
61	        DIAGCTL_CODE_DIAG => diag_print(caller, msg),
62	        // Reserved MINIX 3 subcodes. Kernel message-log subscription
63	        // (REGISTER/UNREGISTER) and stack traces need machinery minix.rs does
64	        // not have yet; the numbers are held so they cannot be reused.
65	        DIAGCTL_CODE_STACKTRACE | DIAGCTL_CODE_REGISTER | DIAGCTL_CODE_UNREGISTER => EINVAL,
66	        _ => EINVAL,
67	    }
68	}
69	
70	/// `DIAGCTL_CODE_DIAG`: emit `[diag <name>] <text>`.
71	///
72	/// Deliberately unsampled — a sampled debug channel is useless. The rate is
73	/// caller-controlled, so a runaway server can saturate the PL011 and crowd out
74	/// the boot log; that is the same bargain MINIX makes, and the alternative
75	/// (dropping lines) would make the channel untrustworthy.
76	fn diag_print(caller: &Proc, msg: &Message) -> i32 {
77	    let len = read_i32(msg, 4);
78	    if len < 0 || len as usize > DIAG_TEXT_MAX {
79	        return EINVAL;
80	    }
81	    let len = len as usize;
82	
83	    let mut uart = Uart::new();
84	    let _ = write!(uart, "[diag {}] ", NameStr(&caller.name));
85	    for &b in &msg.payload[DIAG_TEXT_OFF..DIAG_TEXT_OFF + len] {
86	        // Printable ASCII only; anything else (newline, CR, escape, high bit)
87	        // becomes '.' so one call is always exactly one line.
88	        let c = if (0x20..=0x7E).contains(&b) { b } else { b'.' };
89	        let _ = uart.write_char(c as char);
90	    }
91	    let _ = uart.write_char('\n');
92	    OK
93	}
94	
95	/// Render a NUL-padded `Proc::name` as text, stopping at the first NUL and
96	/// substituting `?` for any non-printable byte.
97	///
98	/// A `Display` wrapper rather than a `str` conversion so a name that is not
99	/// valid UTF-8 still prints something identifying instead of collapsing the
100	/// whole prefix. Slice 4.7's `do_exec` does the equivalent inline; this call
101	/// prints far more often, so it gets a helper.
102	struct NameStr<'a>(&'a [u8]);
103	
104	impl core::fmt::Display for NameStr<'_> {
105	    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
106	        for &b in self.0 {
107	            if b == 0 {
108	                break;
109	            }
110	            let c = if (0x20..=0x7E).contains(&b) { b } else { b'?' };
111	            f.write_char(c as char)?;
112	        }
113	        Ok(())
114	    }
115	}
116	
117	/// Read a native-endian i32 from payload `off..off+4`.
118	fn read_i32(m: &Message, off: usize) -> i32 {
119	    i32::from_ne_bytes(
120	        m.payload[off..off + 4]
121	            .try_into()
122	            .expect("payload in range"),
123	    )
124	}
