63	/// Leading `SYS_EXIT` calls traced explicitly, plus an every-100th steady
64	/// sample — fork/exit churn makes exits steady-state as of 4.6, so a
65	/// head-only trace (the 4.5 shape) would go silent seconds into boot.
66	const EXIT_TRACE_HEAD: u64 = 6;
67	const EXIT_TRACE_EVERY: u64 = 100;
68	static EXIT_COUNT: AtomicU64 = AtomicU64::new(0);
69	
70	/// `SYS_EXIT` — permanently stop the target, detach it from IPC, tear down
71	/// its address space, and free its slot.
72	pub(super) fn do_exit(
73	    proc_table: &mut [Proc; N_PROC_SLOTS],
74	    priv_table: &mut [Priv; NR_SYS_PROCS],
75	    caller_nr: ProcNr,
76	    msg: &mut Message,
77	) -> i32 {
78	    let target_e: Endpoint = read_i32(msg, 0);
79	
80	    if target_e == SELF {
81	        return EINVAL;
82	    }
83	    let target_idx = match okendpt(proc_table, target_e) {
84	        Ok(idx) => idx,
85	        Err(e) => return e,
86	    };
87	    // The SELF sentinel is rejected above, but the caller could also name its
88	    // own endpoint explicitly — same active-TTBR0 hazard, same answer.
89	    if proc_index(caller_nr) == Some(target_idx) {
90	        return EINVAL;
91	    }
92	
93	    let (rts, sendto_e, nr, name0, dead_e, ttbr0_pa, dead_asid, dead_priv_id) = {
94	        let p = &mut proc_table[target_idx];
95	        let rts = p.rts_flags.load(Ordering::Relaxed);
96	        p.alarm_at = 0;
97	        let out = (
98	            rts, p.sendto_e, p.nr, p.name[0], p.endpoint, p.ttbr0_pa, p.asid, p.priv_id,
99	        );
100	        // SAFETY: single-threaded EL1 context; the exclusive `p` borrow ends
101	        // (NLL) as `rts_set` captures `nr` internally — it dequeues the target
102	        // if it was runnable.
103	        unsafe { sched::rts_set(p, RTS_PROC_STOP) };
104	        out
105	    };
106	
107	    // A proc blocked SENDING sits on exactly one caller queue — the
108	    // destination named by its `sendto_e` (classic MINIX `clear_proc` walks
109	    // only that chain too). Unlink it so the dead proc's queued message is
110	    // never delivered.
111	    if rts & RTS_SENDING != 0 {
112	        unlink_from_caller_q(proc_table, target_idx, sendto_e);
113	    }
114	
115	    unblock_dependents(proc_table, priv_table, target_idx, dead_e, nr, dead_priv_id);
116	
117	    let freed_pages = teardown_addrspace(ttbr0_pa, dead_asid);
118	
119	    free_slot(&mut proc_table[target_idx]);
120	
121	    let n = EXIT_COUNT.fetch_add(1, Ordering::Relaxed) + 1;
122	    if n <= EXIT_TRACE_HEAD || n.is_multiple_of(EXIT_TRACE_EVERY) {
123	        let _ = writeln!(
124	            Uart::new(),
125	            "[ksys SYS_EXIT] target={} nr={} freed={freed_pages} result=0",
126	            name0 as char,
127	            nr.get(),
128	        );
129	    }
130	    OK
131	}
132	
133	/// Wake every process blocked on the dead endpoint with `EDEADSRCDST`
134	/// (MINIX 3 `kernel/system.c` `clear_ipc_refs`).
135	///
136	/// A blocked proc's dependency is `sendto_e` when `RTS_SENDING` is set (the
137	/// SENDREC send-half case carries both bits — SENDING wins, matching MINIX's
138	/// `P_BLOCKEDON`), else `getfrom_e` when `RTS_RECEIVING`. Matching procs get
139	/// the error patched into their parked SVC frame's `x0` (the register the
140	/// trap restore path hands back — the MINIX `retreg` pattern), their queue
141	/// linkage cleared, and both IPC block bits unset; `rts_unset` enqueues any
142	/// that become runnable. `RECEIVE(ANY)` blockers are untouched (`ANY` never
143	/// equals a real endpoint).
144	///
145	/// When the dead proc *owns* a dedicated priv slot (`priv.proc_nr` names it),
146	/// its pending-notification footprint is purged: its sender bit is cleared
147	/// from every priv's `notify_pending`, its own map is zeroed, and the slot is
148	/// detached. A shared priv slot (the `USER_PRIV_ID` case — every forked child
149	/// aliases it) is deliberately left alone: its bitmap state belongs to all
150	/// its live procs collectively, and `USR_T` (SENDREC-only) procs can never
151	/// have set a notify bit anyway.
152	fn unblock_dependents(
153	    proc_table: &mut [Proc; N_PROC_SLOTS],
154	    priv_table: &mut [Priv; NR_SYS_PROCS],
155	    target_idx: usize,
156	    dead_e: Endpoint,
157	    dead_nr: ProcNr,
158	    dead_priv_id: Option<minixrs_kernel_shared::PrivId>,
159	) {
160	    for (idx, p) in proc_table.iter_mut().enumerate() {
161	        if idx == target_idx {
162	            continue;
163	        }
164	        let rts = p.rts_flags.load(Ordering::Relaxed);
165	        if rts & RTS_SLOT_FREE != 0 {
166	            continue;
167	        }
168	        let blocked_on = if rts & RTS_SENDING != 0 {
169	            p.sendto_e
170	        } else if rts & RTS_RECEIVING != 0 {
171	            p.getfrom_e
172	        } else {
173	            continue;
174	        };
175	        if blocked_on != dead_e {
176	            continue;
177	        }
178	        p.regs.x[0] = EDEADSRCDST as i64 as u64;
179	        p.q_link = None;
180	        p.sendto_e = NONE;
181	        p.getfrom_e = NONE;
182	        p.misc_flags &= !MF_REPLY_PEND;
183	        // SAFETY: single-threaded EL1 context; the exclusive `p` borrow ends
184	        // (NLL) as `rts_unset` captures `nr` internally — it enqueues the
185	        // proc if the IPC bits were its only block state.
186	        unsafe { sched::rts_unset(p, RTS_SENDING | RTS_RECEIVING) };
187	    }
188	    // Every sender the loop woke was on the dead proc's caller_q; the chain
189	    // is now meaningless, so drop the head.
190	    proc_table[target_idx].caller_q = None;
191	
192	    if let Some(pid) = dead_priv_id {
193	        let pidx = pid.as_usize();
194	        if pidx < NR_SYS_PROCS && priv_table[pidx].proc_nr == Some(dead_nr) {
195	            for pv in priv_table.iter_mut() {
196	                clear_sys_bit(&mut pv.notify_pending, pid);
197	            }
198	            priv_table[pidx].notify_pending = [0; IPC_MAP_CHUNKS];
199	            priv_table[pidx].proc_nr = None;
200	        }
201	    }
202	}
203	
204	/// Free every leaf frame in the dead proc's page-table tree, invalidate its
205	/// TLB entries, free the tree itself, and recycle the ASID. Returns the leaf
206	/// count (the trace's frame-leak canary). No-op for procs that never ran at
207	/// EL0 (`ttbr0_pa == 0`: kernel tasks, never-loaded boot servers).
208	///
209	/// Shared with `do_exec`, which reuses it to reclaim the *old* image's address
210	/// space after swapping in the new one — the same "not the active TTBR0"
211	/// invariant holds there (exec's target is never the running caller).
212	pub(super) fn teardown_addrspace(ttbr0_pa: u64, dead_asid: u8) -> u64 {
213	    if ttbr0_pa == 0 {
214	        return 0;
215	    }
216	    let mut freed: u64 = 0;
217	    // The leaf walk must precede `destroy` (which frees the tables the walk
218	    // reads). Leaf frames are exclusively the dead proc's: fork copies pages
219	    // rather than sharing them, and `VMCTL_PT_MAP` allocates fresh frames.
220	    let _ = walk_leaves(ttbr0_pa, &mut |_va, pa, _prot| {
221	        free_frame(Frame::from_addr(pa));
222	        freed += 1;
223	        Ok(())
224	    });
225	    // SAFETY: single-threaded EL1; the dead proc's AS is never the active
226	    // TTBR0 (self-exit is rejected), so invalidating its ASID cannot yank
227	    // translations out from under the running caller.
228	    unsafe { mmu::flush_tlb_asid(dead_asid) };
229	    AddrSpace { ttbr0_pa }.destroy();
230	    // SAFETY: this ASID's TLB entries were invalidated just above, so the
231	    // next `alloc_asid` may hand it to a fresh address space.
232	    unsafe { asid::free_asid(dead_asid) };
233	    freed
234	}
235	
236	/// Reset the slot for reuse: bump the endpoint generation (every stale
237	/// endpoint now fails `okendpt`), zero all per-process state, and mark the
238	/// slot free. `nr` and the bumped `endpoint` survive — `SYS_FORK` consumes
239	/// the stored endpoint when it re-populates the slot.
240	fn free_slot(p: &mut Proc) {
241	    p.endpoint = bump_generation(p.endpoint);
242	    p.priv_id = None;
243	    p.misc_flags = 0;
244	    p.sig_pending = 0;
245	    p.alarm_at = 0;
246	    p.user_time = 0;
247	    p.sys_time = 0;
248	    p.caller_q = None;
249	    p.q_link = None;
250	    p.getfrom_e = NONE;
251	    p.sendto_e = NONE;
252	    p.deliver_msg_vir = 0;
253	    p.ttbr0_pa = 0;
254	    p.asid = 0;
255	    p.page_fault_state = PageFaultState::EMPTY;
256	    p.heap_window = HeapWindow::EMPTY;
257	    p.scheduler = NONE;
258	    p.next_ready = None;
259	    p.rts_flags.store(RTS_SLOT_FREE, Ordering::Relaxed);
260	}
261	
262	/// Splice `target_idx` out of the `caller_q` chain of the proc named by
263	/// `sendto_e`. No-op if the destination is invalid or the target isn't on the
264	/// chain (both indicate the flags and queue already diverged; nothing to fix
265	/// here). All borrows are sequential single-slot index accesses.
266	fn unlink_from_caller_q(
267	    proc_table: &mut [Proc; N_PROC_SLOTS],
268	    target_idx: usize,
269	    sendto_e: Endpoint,
270	) {
271	    use minixrs_kernel_shared::endpoint::endpoint_proc;
272	    let Some(dst_idx) = proc_index(endpoint_proc(sendto_e)) else {
273	        return;
274	    };
275	    let target_nr = proc_table[target_idx].nr;
276	    let target_link = proc_table[target_idx].q_link;
277	
278	    if proc_table[dst_idx].caller_q == Some(target_nr) {
279	        proc_table[dst_idx].caller_q = target_link;
280	        proc_table[target_idx].q_link = None;
281	        return;
282	    }
283	
284	    // Walk for the predecessor. Chains are Option<ProcNr>-linked and acyclic
285	    // (each proc is on at most one caller queue), so this terminates.
286	    let mut cur = proc_table[dst_idx].caller_q;
287	    while let Some(cur_nr) = cur {
288	        let Some(cur_idx) = proc_index(cur_nr) else {
289	            return;
290	        };
291	        if proc_table[cur_idx].q_link == Some(target_nr) {
292	            proc_table[cur_idx].q_link = target_link;
293	            proc_table[target_idx].q_link = None;
294	            return;
295	        }
296	        cur = proc_table[cur_idx].q_link;
297	    }
298	}
299	
300	#[inline]
301	fn read_i32(msg: &Message, off: usize) -> i32 {
302	    i32::from_ne_bytes(
303	        msg.payload[off..off + 4]
304	            .try_into()
305	            .expect("payload in range"),
306	    )
307	}
