8	//! Kernel-internal flag bits for [`Proc`] and [`Priv`].
9	//!
10	//! [`Proc`]: super::Proc
11	//! [`Priv`]: super::Priv
12	//!
13	//! Values mirror MINIX 3 `kernel/proc.h` (RTS / MF) and `include/minix/const.h`
14	//! (PREEMPTIBLE / BILLABLE / …) so the bit semantics are recognizable. None
15	//! of these constants belong on the IPC wire — userspace never sees them —
16	//! so they live in the kernel crate rather than in `kernel-shared`.
17	//!
18	//! minix.rs drops a few MINIX 3 flags that are not relevant to the port:
19	//! `LU_SYS_PROC` (no live update), `MF_FLUSH_TLB` / `MF_SPROF_SEEN` (no SMP,
20	//! no profiling), `MF_SC_*` (no syscall tracing).
21	
22	use minixrs_kernel_shared::ipc_const::{RECEIVE, SENDREC};
23	
24	// ---------------------------------------------------------------------------
25	// Run-time state flags (`Proc::rts_flags`).
26	//
27	// A process is runnable iff `rts_flags == 0`. Each bit identifies a distinct
28	// reason the kernel is keeping the process off the run queue; clearing all
29	// reasons makes the process runnable again.
30	// ---------------------------------------------------------------------------
31	
32	/// Process-table slot is free.
33	pub const RTS_SLOT_FREE: u32 = 0x0_0001;
34	/// Process has been explicitly stopped.
35	pub const RTS_PROC_STOP: u32 = 0x0_0002;
36	/// Blocked trying to `SEND`.
37	pub const RTS_SENDING: u32 = 0x0_0004;
38	/// Blocked trying to `RECEIVE`.
39	pub const RTS_RECEIVING: u32 = 0x0_0008;
40	/// A kernel signal has arrived for this process.
41	pub const RTS_SIGNALED: u32 = 0x0_0010;
42	/// Signal handling is in progress.
43	pub const RTS_SIG_PENDING: u32 = 0x0_0020;
44	/// Process is being traced (debugger / ptrace).
45	pub const RTS_P_STOP: u32 = 0x0_0040;
46	/// Forked system process awaiting privilege assignment.
47	pub const RTS_NO_PRIV: u32 = 0x0_0080;
48	/// Process cannot send or receive — no valid endpoint.
49	pub const RTS_NO_ENDPOINT: u32 = 0x0_0100;
50	/// Awaiting VM to set up page tables.
51	pub const RTS_VMINHIBIT: u32 = 0x0_0200;
52	/// Unhandled page fault pending.
53	pub const RTS_PAGEFAULT: u32 = 0x0_0400;
54	/// Originator of a VM memory request, waiting on resolution.
55	pub const RTS_VMREQUEST: u32 = 0x0_0800;
56	/// Target of a VM memory request, helping the originator.
57	pub const RTS_VMREQTARGET: u32 = 0x0_1000;
58	/// Preempted by a higher-priority process — re-enqueue at the front.
59	pub const RTS_PREEMPTED: u32 = 0x0_4000;
60	/// Quantum exhausted — re-enqueue at the back of the run queue.
61	pub const RTS_NO_QUANTUM: u32 = 0x0_8000;
62	/// Awaiting VM to finish boot-time setup.
63	pub const RTS_BOOTINHIBIT: u32 = 0x1_0000;
64	
65	// ---------------------------------------------------------------------------
66	// Miscellaneous flags (`Proc::misc_flags`).
67	//
68	// These do NOT block scheduling; they are status bits the kernel consults
69	// during IPC, signal delivery, and FPU handling.
70	// ---------------------------------------------------------------------------
71	
72	pub const MF_REPLY_PEND: u32 = 0x0_0001;
73	pub const MF_VIRT_TIMER: u32 = 0x0_0002;
74	pub const MF_PROF_TIMER: u32 = 0x0_0004;
75	pub const MF_KCALL_RESUME: u32 = 0x0_0008;
76	pub const MF_DELIVERMSG: u32 = 0x0_0040;
77	pub const MF_SIG_DELAY: u32 = 0x0_0080;
78	pub const MF_FPU_INITIALIZED: u32 = 0x0_1000;
79	pub const MF_SENDING_FROM_KERNEL: u32 = 0x0_2000;
80	pub const MF_CONTEXT_SET: u32 = 0x0_4000;
81	pub const MF_SENDA_VM_MISS: u32 = 0x2_0000;
82	pub const MF_STEP: u32 = 0x4_0000;
83	pub const MF_MSGFAILED: u32 = 0x8_0000;
84	pub const MF_NICED: u32 = 0x10_0000;
85	
86	// ---------------------------------------------------------------------------
87	// Privilege flags (`Priv::flags`). 16-bit to match `Priv`'s field width.
88	// ---------------------------------------------------------------------------
89	
90	/// Process is preemptible (kernel tasks are not).
91	pub const PREEMPTIBLE: u16 = 0x002;
92	/// CPU time is charged to this process.
93	pub const BILLABLE: u16 = 0x004;
94	/// Privilege ID was assigned dynamically (not from the boot image).
95	pub const DYN_PRIV_ID: u16 = 0x008;
96	/// System process — owns its own [`Priv`] slot.
97	///
98	/// [`Priv`]: super::Priv
99	pub const SYS_PROC: u16 = 0x010;
100	/// Privilege subsystem checks I/O port access requests against `Priv::io_ranges`.
101	pub const CHECK_IO_PORT: u16 = 0x020;
102	/// Privilege subsystem checks IRQ assignments against `Priv::irqs`.
103	pub const CHECK_IRQ: u16 = 0x040;
104	/// Privilege subsystem checks VM memory-range requests against `Priv::mem_ranges`.
105	pub const CHECK_MEM: u16 = 0x080;
106	/// Root system process (the reincarnation server, RS).
107	pub const ROOT_SYS_PROC: u16 = 0x100;
108	/// VM system process — gets the dedicated VM privilege role.
109	pub const VM_SYS_PROC: u16 = 0x200;
110	/// Restarted system process (set on respawn).
111	pub const RST_SYS_PROC: u16 = 0x800;
112	
113	// ---------------------------------------------------------------------------
114	// Trap masks (`Priv::trap_mask`). Bit `i` allows IPC primitive `i`.
115	// ---------------------------------------------------------------------------
116	
117	/// Kernel-task trap mask — no IPC traps allowed (HARDWARE, IDLE, ASYNCM).
118	pub const TSK_T: u16 = 0;
119	/// "Constrained" kernel-task trap mask — only `RECEIVE` allowed (CLOCK, SYSTEM).
120	pub const CSK_T: u16 = 1 << RECEIVE;
121	/// User-process trap mask — only `SENDREC` allowed.
122	pub const USR_T: u16 = 1 << SENDREC;
123	/// System-server trap mask — all IPC primitives allowed.
124	pub const SRV_T: u16 = !0;
