3	//! Kernel debug-channel client — `SYS_DIAGCTL` (slice 5.1).
4	//!
5	//! Servers run at EL0 with no console. [`diag_print`] is how they get text onto
6	//! the serial line: a `SYS_DIAGCTL` kernel call carrying the text inline in the
7	//! message payload, which the kernel prints prefixed with the caller's own name.
8	//!
9	//! This is the *debug* channel, deliberately independent of the eventual stdio
10	//! path (VFS → TTY, slices 5.3/5.4) — it has to keep working while those, and
11	//! the grant machinery they depend on, are still being built.
12	//!
13	//! Like [`crate::sef`] and [`crate::ds`], this issues an IPC trap, so it is
14	//! excluded from host coverage and verified by the QEMU boot trace. The chunk
15	//! arithmetic is factored out as a pure helper and unit-tested.
16	
17	use minixrs_ipc::ipc_sendrec;
18	use minixrs_kernel_shared::Message;
19	use minixrs_kernel_shared::callnr::{DIAG_TEXT_MAX, DIAG_TEXT_OFF, DIAGCTL_CODE_DIAG, SYS_DIAGCTL};
20	use minixrs_kernel_shared::com::{SYSTEM, boot_endpoint};
21	use minixrs_kernel_shared::error::OK;
22	
23	/// Print `s` to the kernel console via `SYS_DIAGCTL`.
24	///
25	/// The kernel prefixes each line with the caller's own name as it knows it, so
26	/// a server needs no identifying prefix of its own — `diag_print("sef ready")`
27	/// from VFS emits `[diag vfs] sef ready`.
28	///
29	/// Strings longer than [`DIAG_TEXT_MAX`] are split across successive calls, one
30	/// console line per chunk. Splits happen on **byte** boundaries, not UTF-8
31	/// character boundaries; the kernel replaces every non-printable-ASCII byte
32	/// with `.`, so a split can garble a multi-byte character but can never emit a
33	/// broken line. Keep diag text ASCII.
34	///
35	/// Returns `OK`, or the first non-`OK` result — aborting any remaining chunks
36	/// rather than printing a partial message under a misleading success. An empty
37	/// string sends nothing and returns `OK`.
38	pub fn diag_print(s: &str) -> i32 {
39	    let bytes = s.as_bytes();
40	    let mut sent = 0usize;
41	    while sent < bytes.len() {
42	        let n = chunk_len(bytes.len() - sent);
43	        let rc = diag_send(&bytes[sent..sent + n]);
44	        if rc != OK {
45	            return rc;
46	        }
47	        sent += n;
48	    }
49	    OK
50	}
51	
52	/// Bytes to place in the next `SYS_DIAGCTL` call given `remaining` still to
53	/// send: the whole remainder, capped at the payload's inline text budget.
54	///
55	/// Trivial, but it is the one piece of [`diag_print`] that can be host-tested,
56	/// and an off-by-one here would silently truncate every long diag line.
57	fn chunk_len(remaining: usize) -> usize {
58	    if remaining < DIAG_TEXT_MAX {
59	        remaining
60	    } else {
61	        DIAG_TEXT_MAX
62	    }
63	}
64	
65	/// Issue one `SYS_DIAGCTL(DIAGCTL_CODE_DIAG)` carrying `bytes` inline.
66	///
67	/// Returns the IPC trap's error if the SENDREC itself failed, else the kernel's
68	/// reply `m_type` — the same two-step check `sef_startup` and
69	/// `sef_publish_to_ds` use, since a trap-level failure and a call-level failure
70	/// arrive by different routes.
71	fn diag_send(bytes: &[u8]) -> i32 {
72	    let mut msg = Message {
73	        m_source: 0,
74	        m_type: SYS_DIAGCTL,
75	        payload: [0u8; 96],
76	    };
77	    msg.payload[0..4].copy_from_slice(&DIAGCTL_CODE_DIAG.to_ne_bytes());
78	    msg.payload[4..8].copy_from_slice(&(bytes.len() as i32).to_ne_bytes());
79	    msg.payload[DIAG_TEXT_OFF..DIAG_TEXT_OFF + bytes.len()].copy_from_slice(bytes);
80	
81	    let trap_rc = ipc_sendrec(boot_endpoint(SYSTEM), &mut msg);
82	    if trap_rc != OK {
83	        return trap_rc;
84	    }
85	    msg.m_type
86	}
87	
88	#[cfg(test)]
89	mod tests {
90	    use super::*;
91	
92	    #[test]
93	    fn chunk_len_passes_short_strings_whole() {
94	        assert_eq!(chunk_len(0), 0);
95	        assert_eq!(chunk_len(1), 1);
96	        assert_eq!(chunk_len(DIAG_TEXT_MAX - 1), DIAG_TEXT_MAX - 1);
97	    }
98	
99	    #[test]
100	    fn chunk_len_caps_at_the_payload_budget() {
101	        assert_eq!(chunk_len(DIAG_TEXT_MAX), DIAG_TEXT_MAX);
102	        assert_eq!(chunk_len(DIAG_TEXT_MAX + 1), DIAG_TEXT_MAX);
103	        assert_eq!(chunk_len(10 * DIAG_TEXT_MAX), DIAG_TEXT_MAX);
104	    }
105	
106	    #[test]
107	    fn chunking_covers_every_byte_exactly_once() {
108	        // Mirror `diag_print`'s loop without the IPC trap: the chunk lengths
109	        // must tile the input with no gap, overlap, or zero-length step.
110	        for total in [
111	            0,
112	            1,
113	            DIAG_TEXT_MAX - 1,
114	            DIAG_TEXT_MAX,
115	            DIAG_TEXT_MAX + 1,
116	            500,
117	        ] {
118	            let mut sent = 0usize;
119	            let mut steps = 0usize;
120	            while sent < total {
121	                let n = chunk_len(total - sent);
122	                assert!(n > 0, "a zero-length chunk would loop forever");
123	                assert!(n <= DIAG_TEXT_MAX);
124	                sent += n;
125	                steps += 1;
126	                assert!(steps <= total + 1, "chunking failed to converge");
127	            }
128	            assert_eq!(sent, total);
129	        }
130	    }
131	}
