57	/// Priority band and quantum PM assigns a forked child via `SCHEDULING_START`.
58	/// These match SCHED's own `USER_Q` / `QUANTUM` (`servers/sched/src/policy.rs`)
59	/// so a child round-robins in the managed band rather than sinking behind the
60	/// kernel-scheduled stubs.
61	const CHILD_PRIORITY: i32 = 8;
62	const CHILD_QUANTUM: i32 = 5;
63	
64	/// The boot-embedded binary PM's `execve` selects (slice 4.7). Until the
65	/// filesystem/musl wrappers thread a user-supplied path (Phase 5), PM always
66	/// execs the `worker` demo binary — the kernel resolves it by name in the MXBI
67	/// archive. Must be `<= EXEC_NAME_LEN` bytes to fit the `SYS_EXEC` payload.
68	const EXEC_TARGET: &str = "worker";
69	const _: () = assert!(EXEC_TARGET.len() <= EXEC_NAME_LEN);
70	
71	/// ELF entry point. The kernel primes `SP_EL0` before `eret`, so `_start`
72	/// dives straight into Rust. Gated to `not(test)` (under `cargo test` the
73	/// crate links as a host binary with the C runtime's `_start`);
74	/// `.text._start` is gated to the bare-metal target so a Mach-O host
75	/// `cargo check` still type-checks.
76	#[cfg(not(test))]
77	#[unsafe(no_mangle)]
78	#[cfg_attr(target_os = "none", unsafe(link_section = ".text._start"))]
79	pub extern "C" fn _start() -> ! {
80	    main()
81	}
82	
83	#[cfg_attr(test, allow(dead_code))]
84	fn main() -> ! {
85	    // `sef_startup` learns PM's endpoint/name via SYS_GETINFO(GET_WHOAMI) and
86	    // runs `pm_init` (DS publish, mproc seed). No signal
87	    // handler: PM *is* the signal manager, not a signal consumer. On failure
88	    // there is nothing to print from EL0 — park forever.
89	    let sef = sef_startup(SefConfig {
90	        init_fresh: Some(pm_init),
91	        signal_handler: None,
92	    })
93	    .unwrap_or_else(|_| {
94	        loop {
95	            core::hint::spin_loop()
96	        }
97	    });
98	
99	    let system = boot_endpoint(SYSTEM);
100	    // VM and SCHED are boot servers at generation 0, so `boot_endpoint` is their
101	    // live endpoint (they never exit in Phase 4). PM drives the fork tree
102	    // through them: VM clones the child's regions, SCHED schedules it.
103	    let vm = boot_endpoint(VM_PROC_NR);
104	    let sched = boot_endpoint(SCHED_PROC_NR);
105	
106	    let mut msg = Message {
107	        m_source: 0,
108	        m_type: 0,
109	        payload: [0u8; 96],
110	    };
111	    loop {
112	        if sef.receive(&mut msg) != OK {
113	            continue;
114	        }
115	        match msg.m_type {
116	            // The kernel's ksig wake-up (`deliver_ksig`): a NOTIFY stamped
117	            // from SYSTEM. RS heartbeat pings are also NOTIFYs but are
118	            // consumed inside `sef.receive` (classified `Ping`), so a NOTIFY
119	            // from any other source here is simply ignored.
120	            NOTIFY_MESSAGE if msg.m_source == system => drain_ksigs(system),
121	            PM_GETPID => handle_getpid(&mut msg),
122	            PM_FORK => handle_fork(system, vm, sched, &mut msg),
123	            PM_EXIT => handle_exit(system, sched, &mut msg),
124	            PM_WAIT => handle_wait(&mut msg),
125	            PM_EXEC => handle_exec(system, &mut msg),
126	            // Unknown request: drop it.
127	            _ => {}
128	        }
129	    }
130	}
