132	/// SEF fresh-init callback: publish PM's endpoint to DS and seed the mproc
133	/// table. init (PID 1) — the live fork/exec/wait driver that replaced the
134	/// slice-4.6 stub E demo — is a real boot process made runnable by the kernel
135	/// boot loader, so PM no longer hand-releases a frozen stub here.
136	#[cfg_attr(test, allow(dead_code))]
137	fn pm_init(_endpoint: Endpoint, name: &[u8; SYS_GETINFO_NAME_LEN]) -> i32 {
138	    let rc = sef_publish_to_ds(name);
139	    if rc != OK {
140	        return rc;
141	    }
142	    mproc::seed();
143	    OK
144	}
