146	/// Handle `PM_GETPID`: reply `m_type = pid` (MINIX result-is-pid convention;
147	/// errors negative) with the parent's pid in payload `0..4`, so `getppid`
148	/// needs no second call. The caller is identified by the kernel-stamped
149	/// `m_source` — there is no spoofable request payload.
150	#[cfg_attr(test, allow(dead_code))]
151	fn handle_getpid(msg: &mut Message) {
152	    let caller_e = msg.m_source;
153	    let result = match usize::try_from(endpoint_proc(caller_e).get())
154	        .ok()
155	        .and_then(mproc::getpid)
156	    {
157	        Some((pid, ppid)) => {
158	            wr_i32(msg, 0, ppid);
159	            pid
160	        }
161	        None => ESRCH,
162	    };
163	    reply(caller_e, msg, result);
164	}
165	
166	/// Handle `PM_FORK`: create a child of the caller. PM allocates a child slot,
167	/// then drives the whole tree — `SYS_FORK` (kernel clones the frozen child +
168	/// its address space), `VM_FORK` (VM clones the region set), `SCHEDULING_START`
169	/// (SCHED schedules the still-frozen child), and `SYS_PRIVCTL(PRIVCTL_SET_USER)`
170	/// (release the freeze; the child stays a blocked receiver). Finally PM wakes
171	/// **both** halves of the shared blocked SENDREC: the child's reply carries
172	/// `m_type = 0`, the parent's carries the child pid. The ordering is deliberate
173	/// — release before the replies, and the replies last — so the child cannot run
174	/// until its identity, memory, and scheduling are fully set up.
175	#[cfg_attr(test, allow(dead_code))]
176	fn handle_fork(system: Endpoint, vm: Endpoint, sched: Endpoint, msg: &mut Message) {
177	    let parent_e = msg.m_source;
178	    let Some(parent_slot) = usize::try_from(endpoint_proc(parent_e).get()).ok() else {
179	        return reply(parent_e, msg, EINVAL);
180	    };
181	    if !mproc::in_use(parent_slot) {
182	        return reply(parent_e, msg, EINVAL);
183	    }
184	
185	    // Allocate the child's slot (= its kernel proc number). Bail before any
186	    // kernel work if the table is full — recovery mid-fork is a nuisance.
187	    let Some(child_slot) = mproc::alloc_slot() else {
188	        return reply(parent_e, msg, EAGAIN);
189	    };
190	
191	    // Kernel fork: clone the parent into the frozen child; get its endpoint.
192	    let (rc, child_e) = sys_fork(system, parent_e, child_slot as i32);
193	    if rc != OK {
194	        mproc::cleanup(child_slot);
195	        return reply(parent_e, msg, rc);
196	    }
197	
198	    // VM: clone the parent's region set into the child. On failure, roll the
199	    // kernel fork back before returning the error to the parent.
200	    let vrc = vm_fork(vm, parent_e, child_e);
201	    if vrc != OK {
202	        let _ = sys_exit(system, child_e);
203	        mproc::cleanup(child_slot);
204	        return reply(parent_e, msg, vrc);
205	    }
206	
207	    // SCHED schedules the (still-frozen) child. On failure, roll back like the
208	    // VM step above so we never record an unschedulable child.
209	    let src = sched_start(sched, child_e, CHILD_PRIORITY, CHILD_QUANTUM);
210	    if src != OK {
211	        let _ = sys_exit(system, child_e);
212	        mproc::cleanup(child_slot);
213	        return reply(parent_e, msg, src);
214	    }
215	
216	    // Release the freeze; the child stays RTS_RECEIVING — a blocked receiver,
217	    // off the run queue — until its reply below clears the last block bit. On
218	    // failure roll back like `handle_exit` — stop SCHED first (endpoint still
219	    // valid), then tear the child down — so a child that never became runnable
220	    // is never recorded as "live" (which would hang the parent's `wait()`
221	    // forever). Both calls are boot-server-backed and don't fail with correct
222	    // wiring; this is defense-in-depth.
223	    let prc = privctl_set_user(system, child_e);
224	    if prc != OK {
225	        let _ = sched_stop(sched, child_e);
226	        let _ = sys_exit(system, child_e);
227	        mproc::cleanup(child_slot);
228	        return reply(parent_e, msg, prc);
229	    }
230	
231	    let child_pid = mproc::set_child(child_slot, parent_slot, child_e);
232	
233	    // Wake both halves. Child returns 0 (it is the child); parent returns the
234	    // child pid. Reuse `msg` for both — the kernel snapshots each send.
235	    reply(child_e, msg, 0);
236	    reply(parent_e, msg, child_pid);
237	}
238	
239	/// Handle `PM_EXIT`: terminate the caller with the status in payload `0..4`.
240	/// PM hands the child back to the kernel scheduler (`SCHEDULING_STOP`, while its
241	/// endpoint is still valid) then tears it down (`SYS_EXIT`, a full teardown). It
242	/// keeps the `mproc` slot as a zombie holding the encoded status. If the parent
243	/// is already blocked in `wait()`, PM wakes it immediately and reaps the zombie;
244	/// otherwise the zombie waits for the parent's next `wait()`. PM sends the
245	/// exiting child no reply — it is gone.
246	#[cfg_attr(test, allow(dead_code))]
247	fn handle_exit(system: Endpoint, sched: Endpoint, msg: &mut Message) {
248	    let child_e = msg.m_source;
249	    let status = rd_i32(msg, 0);
250	    let Some(child_slot) = usize::try_from(endpoint_proc(child_e).get()).ok() else {
251	        return;
252	    };
253	    // Capture the pid while the proc is still live (getpid ignores zombies).
254	    let Some((child_pid, _)) = mproc::getpid(child_slot) else {
255	        return;
256	    };
257	    // Scope limitation: there is no reparenting yet. If the parent already
258	    // exited, `parent_of` falls back to the child itself, so the zombie below is
259	    // never reaped (no live parent will `wait()` for it). Harmless while every
260	    // parent is a long-lived boot stub; reparenting orphans to INIT waits for a
261	    // running INIT (4.8+).
262	    let parent_slot = mproc::parent_of(child_slot).unwrap_or(child_slot);
263	
264	    let _ = sched_stop(sched, child_e);
265	    let _ = sys_exit(system, child_e);
266	    mproc::set_zombie(child_slot, encode_status(status));
267	
268	    // Notify a waiting parent directly — no async SIGCHLD in Phase 4 (the kernel
269	    // signal path default-terminates, which would kill a handler-less parent).
270	    if mproc::is_waiting(parent_slot)
271	        && let Some(parent_e) = mproc::endpoint_of(parent_slot)
272	    {
273	        wr_i32(msg, 0, encode_status(status));
274	        reply(parent_e, msg, child_pid);
275	        mproc::set_waiting(parent_slot, false);
276	        mproc::cleanup(child_slot);
277	    }
278	}
279	
280	/// Handle `PM_WAIT`: reap a child of the caller. If a zombie child exists, reply
281	/// its pid (with the encoded status in payload `0..4`) and free the slot. If a
282	/// live child exists but none has exited, suspend the caller (no reply) — the
283	/// exiting child's `handle_exit` will wake it. With no children, reply `ECHILD`.
284	#[cfg_attr(test, allow(dead_code))]
285	fn handle_wait(msg: &mut Message) {
286	    let parent_e = msg.m_source;
287	    let Some(parent_slot) = usize::try_from(endpoint_proc(parent_e).get()).ok() else {
288	        return reply(parent_e, msg, EINVAL);
289	    };
290	
291	    if let Some((slot, pid, status)) = mproc::find_zombie_child(parent_slot) {
292	        wr_i32(msg, 0, status);
293	        reply(parent_e, msg, pid);
294	        mproc::cleanup(slot);
295	    } else if mproc::has_live_child(parent_slot) {
296	        // SUSPEND: no reply. The caller stays blocked in its SENDREC until a
297	        // child exits and `handle_exit` replies on its behalf.
298	        mproc::set_waiting(parent_slot, true);
299	    } else {
300	        reply(parent_e, msg, ECHILD);
301	    }
302	}
303	
304	/// Handle `PM_EXEC`: replace the caller's program image with the boot-embedded
305	/// [`EXEC_TARGET`]. PM issues `SYS_EXEC` naming the caller (kernel-stamped
306	/// `m_source`); the kernel builds the new address space and resumes the caller
307	/// at the new entry point. On success PM sends **no** reply — the caller does
308	/// not return from this call, it restarts at the new image's `_start`. On
309	/// failure the caller is untouched on its old image, so PM replies the errno.
310	#[cfg_attr(test, allow(dead_code))]
311	fn handle_exec(system: Endpoint, msg: &mut Message) {
312	    let caller_e = msg.m_source;
313	    let rc = sys_exec(system, caller_e, EXEC_TARGET);
314	    if rc != OK {
315	        reply(caller_e, msg, rc);
316	    }
317	    // Success: the kernel already resumed the caller at the new image — no reply.
318	}
319	
320	/// MINIX `W_EXITCODE` for a normal exit: the low byte of `status` in bits 8..16,
321	/// the terminating-signal byte (0 for a normal exit) in bits 0..8.
322	fn encode_status(status: i32) -> i32 {
323	    (status & 0xff) << 8
324	}
325	
326	/// Drain the kernel's pending-signal queue: `SYS_GETKSIG` until it reports
327	/// `NONE`, disposing of each signalled proc. Default disposition is
328	/// terminate (`SYS_EXIT`) for user processes; boot servers are skipped.
329	///
330	/// Contract with the kernel (see `system::do_sig`): every endpoint GETKSIG
331	/// returns must be either terminated or ENDKSIG-acknowledged, or it stays
332	/// signal-pending forever. A *successful* terminate gets **no** `SYS_ENDKSIG`:
333	/// as of slice 4.6 `SYS_EXIT` is a full teardown — signal state zeroed, slot
334	/// freed, endpoint generation bumped — so a post-exit acknowledge would only
335	/// bounce off `okendpt` with `EDEADSRCDST`. (MINIX can acknowledge after
336	/// terminate because its `sys_clear` is deferred behind VFS; minix.rs tears
337	/// down immediately.) GETKSIG's scan gates on `sig_pending != 0`, which the
338	/// exit zeroed, so the dead proc is never re-returned. A *rejected* exit,
339	/// however, leaves the slot live with `sig_pending` already handed off — so
340	/// it falls back to `SYS_ENDKSIG` to clear the RTS signal state, keeping the
341	/// dispose-exactly-once invariant even when teardown can't proceed.
342	#[cfg_attr(test, allow(dead_code))]
343	fn drain_ksigs(system: Endpoint) {
344	    loop {
345	        let mut m = Message {
346	            m_source: 0,
347	            m_type: SYS_GETKSIG,
348	            payload: [0u8; 96],
349	        };
350	        if ipc_sendrec(system, &mut m) != OK || m.m_type != OK {
351	            return;
352	        }
353	        let target_e: Endpoint = rd_i32(&m, 0);
354	        if target_e == NONE {
355	            return;
356	        }
357	
358	        // Disposition. The signal bitmap (payload 4..8) is not consulted
359	        // beyond the kernel's guarantee that it is non-empty: with no
360	        // handlers, masks, or an ignore set in Phase 4, every signal shares
361	        // the terminate default.
362	        let action = usize::try_from(endpoint_proc(target_e).get())
363	            .ok()
364	            .map(mproc::handle_kill)
365	            .unwrap_or(mproc::KillAction::NotFound);
366	        if matches!(action, mproc::KillAction::Terminate) {
367	            // Happy path: SYS_EXIT tears the target down (signal state zeroed,
368	            // slot freed) so no acknowledge follows — a post-exit ENDKSIG
369	            // would just bounce off `okendpt`. But if the exit is *rejected*
370	            // the slot stays live, and since GETKSIG already handed off
371	            // `sig_pending` the scan will never re-return it — so fall back to
372	            // ENDKSIG to clear the RTS signal state. Every drained endpoint is
373	            // thus disposed of exactly once.
374	            if sys_exit(system, target_e) != OK {
375	                sys_endksig(system, target_e);
376	            }
377	        } else {
378	            sys_endksig(system, target_e);
379	        }
380	    }
381	}
382	
383	/// `SYS_EXIT` — terminate `target_e` (SENDREC to SYSTEM). Returns the
384	/// kernel-call result so `drain_ksigs` can tell a real teardown from a
385	/// rejected one.
386	#[cfg_attr(test, allow(dead_code))]
387	fn sys_exit(system: Endpoint, target_e: Endpoint) -> i32 {
388	    let mut m = Message {
389	        m_source: 0,
390	        m_type: SYS_EXIT,
391	        payload: [0u8; 96],
392	    };
393	    wr_i32(&mut m, 0, target_e);
394	    let rc = ipc_sendrec(system, &mut m);
395	    if rc != OK {
396	        return rc;
397	    }
398	    m.m_type
399	}
400	
401	/// `SYS_ENDKSIG` — acknowledge `target_e`'s signals as handled.
402	#[cfg_attr(test, allow(dead_code))]
403	fn sys_endksig(system: Endpoint, target_e: Endpoint) {
404	    let mut m = Message {
405	        m_source: 0,
406	        m_type: SYS_ENDKSIG,
407	        payload: [0u8; 96],
408	    };
409	    wr_i32(&mut m, 0, target_e);
410	    let _ = ipc_sendrec(system, &mut m);
411	}
412	
413	/// `SYS_PRIVCTL(PRIVCTL_SET_USER)` — point the frozen `target_e` at the
414	/// shared USER priv slot and release it. Returns the kernel-call result.
415	#[cfg_attr(test, allow(dead_code))]
416	fn privctl_set_user(system: Endpoint, target_e: Endpoint) -> i32 {
417	    let mut m = Message {
418	        m_source: 0,
419	        m_type: SYS_PRIVCTL,
420	        payload: [0u8; 96],
421	    };
422	    wr_i32(&mut m, 0, target_e);
423	    wr_i32(&mut m, 4, PRIVCTL_SET_USER);
424	    let rc = ipc_sendrec(system, &mut m);
425	    if rc != OK {
426	        return rc;
427	    }
428	    m.m_type
429	}
430	
431	/// `SYS_FORK` — kernel-clone the blocked `parent_e` into free slot `child_nr`.
432	/// Returns `(kernel_result, child_endpoint)`; the endpoint is meaningful only
433	/// when the result is `OK` (the kernel writes the child's generation-aware
434	/// endpoint into payload `0..4`).
435	#[cfg_attr(test, allow(dead_code))]
436	fn sys_fork(system: Endpoint, parent_e: Endpoint, child_nr: i32) -> (i32, Endpoint) {
437	    let mut m = Message {
438	        m_source: 0,
439	        m_type: SYS_FORK,
440	        payload: [0u8; 96],
441	    };
442	    wr_i32(&mut m, 0, parent_e);
443	    wr_i32(&mut m, 4, child_nr);
444	    let rc = ipc_sendrec(system, &mut m);
445	    if rc != OK {
446	        return (rc, NONE);
447	    }
448	    (m.m_type, rd_i32(&m, 0))
449	}
450	
451	/// `SYS_EXEC` — ask the kernel to replace `target_e`'s image with the
452	/// boot-embedded binary `name` (SENDREC to SYSTEM). Payload: target endpoint in
453	/// `0..4`, the NUL-padded name in `4..4+EXEC_NAME_LEN`. Returns the kernel-call
454	/// result; on `OK` the kernel has already resumed the target at the new entry.
455	#[cfg_attr(test, allow(dead_code))]
456	fn sys_exec(system: Endpoint, target_e: Endpoint, name: &str) -> i32 {
457	    let mut m = Message {
458	        m_source: 0,
459	        m_type: SYS_EXEC,
460	        payload: [0u8; 96],
461	    };
462	    wr_i32(&mut m, 0, target_e);
463	    // `EXEC_TARGET` is asserted `<= EXEC_NAME_LEN`, so the name fits the field.
464	    let bytes = name.as_bytes();
465	    m.payload[4..4 + bytes.len()].copy_from_slice(bytes);
466	    let rc = ipc_sendrec(system, &mut m);
467	    if rc != OK {
468	        return rc;
469	    }
470	    m.m_type
471	}
472	
473	/// `VM_FORK` — ask VM to clone `parent_e`'s region set into `child_e` (SENDREC
474	/// to VM). Returns VM's reply `m_type`.
475	#[cfg_attr(test, allow(dead_code))]
476	fn vm_fork(vm: Endpoint, parent_e: Endpoint, child_e: Endpoint) -> i32 {
477	    let mut m = Message {
478	        m_source: 0,
479	        m_type: VM_FORK,
480	        payload: [0u8; 96],
481	    };
482	    wr_i32(&mut m, 0, parent_e);
483	    wr_i32(&mut m, 4, child_e);
484	    let rc = ipc_sendrec(vm, &mut m);
485	    if rc != OK {
486	        return rc;
487	    }
488	    m.m_type
489	}
490	
491	/// `SCHEDULING_START` — ask SCHED to begin scheduling `target_e` at the given
492	/// priority/quantum (SENDREC to SCHED). Returns SCHED's reply `m_type`.
493	#[cfg_attr(test, allow(dead_code))]
494	fn sched_start(sched: Endpoint, target_e: Endpoint, priority: i32, quantum: i32) -> i32 {
495	    let mut m = Message {
496	        m_source: 0,
497	        m_type: SCHEDULING_START,
498	        payload: [0u8; 96],
499	    };
500	    wr_i32(&mut m, 0, target_e);
501	    wr_i32(&mut m, 4, priority);
502	    wr_i32(&mut m, 8, quantum);
503	    let rc = ipc_sendrec(sched, &mut m);
504	    if rc != OK {
505	        return rc;
506	    }
507	    m.m_type
508	}
509	
510	/// `SCHEDULING_STOP` — hand `target_e` back to the kernel scheduler (SENDREC to
511	/// SCHED). Called on exit *before* `SYS_EXIT`, while the endpoint is still valid.
512	#[cfg_attr(test, allow(dead_code))]
513	fn sched_stop(sched: Endpoint, target_e: Endpoint) -> i32 {
514	    let mut m = Message {
515	        m_source: 0,
516	        m_type: SCHEDULING_STOP,
517	        payload: [0u8; 96],
518	    };
519	    wr_i32(&mut m, 0, target_e);
520	    let rc = ipc_sendrec(sched, &mut m);
521	    if rc != OK {
522	        return rc;
523	    }
524	    m.m_type
525	}
526	
527	/// Reply to a SENDREC caller: stamp `m_type`, zero `m_source` (the kernel
528	/// overwrites it on delivery), and SEND the message back. Any payload the
529	/// caller wants returned must be written before this call.
530	#[cfg_attr(test, allow(dead_code))]
531	fn reply(target_e: Endpoint, msg: &mut Message, m_type: i32) {
532	    msg.m_type = m_type;
533	    msg.m_source = 0;
534	    let _ = ipc_send(target_e, msg);
535	}
536	
537	/// Read a native-endian i32 from payload `off..off+4`.
538	#[cfg_attr(test, allow(dead_code))]
539	fn rd_i32(m: &Message, off: usize) -> i32 {
540	    i32::from_ne_bytes(m.payload[off..off + 4].try_into().unwrap_or([0; 4]))
541	}
542	
543	/// Write a native-endian i32 into payload `off..off+4`.
544	#[cfg_attr(test, allow(dead_code))]
545	fn wr_i32(m: &mut Message, off: usize, v: i32) {
546	    m.payload[off..off + 4].copy_from_slice(&v.to_ne_bytes());
547	}
548	
549	// The freestanding panic handler; under `cargo test` std supplies its own.
550	#[cfg(not(test))]
551	#[panic_handler]
552	fn panic(_: &core::panic::PanicInfo) -> ! {
553	    loop {
554	        core::hint::spin_loop()
555	    }
556	}
