115	/// Render `minix/callnr.h`.
116	pub fn render() -> String {
117	    let mut f = CFile::new(
118	        "Kernel-call numbers, server request bands, and their payload constants.",
119	        &["kernel-shared/src/callnr.rs"],
120	    );
121	    f.guard_open(GUARD);
122	
123	    f.blank();
124	    f.include(
125	        "minix/ipc.h",
126	        "NOTIFY_MESSAGE, for the band ordering checks",
127	    );
128	
129	    f.block_comment(&[
130	        "Deviation from MINIX 3: its <minix/callnr.h> holds POSIX syscall numbers",
131	        "and keeps server request numbers in <minix/com.h>. minix.rs has no POSIX",
132	        "call-number layer -- a libc wrapper builds a server request directly --",
133	        "so this header carries the kernel calls and the request bands together.",
134	        "",
135	        "Payload byte offsets are not emitted yet: on the Rust side they live in",
136	        "doc comments rather than constants. The first musl wrapper (slice 5.6) is",
137	        "the forcing function for promoting them to real constants.",
138	    ]);
139	
140	    f.section("kernel calls");
141	    f.define_hex("KERNEL_CALL", callnr::KERNEL_CALL.into());
142	    f.blank();
143	    for (name, value) in kernel_calls() {
144	        f.define_hex(name, value.into());
145	    }
146	    f.blank();
147	    // Name-matched with the Rust constant as of slice 5.1 (it was
148	    // `NR_KERN_CALLS_PHASE4` there, and carried a provenance comment here to
149	    // bridge the gap). Keep the two spellings identical past the 5.6 ABI
150	    // freeze — `nr_kern_calls_is_not_phase_suffixed` guards it.
151	    f.define_dec("NR_KERN_CALLS", callnr::NR_KERN_CALLS as i64);
152	    f.define_dec("NR_SYS_CALLS", callnr::NR_SYS_CALLS as i64);
153	
154	    f.section("kernel-call payload constants");
155	    f.define_dec("GET_WHOAMI", callnr::GET_WHOAMI.into());
156	    f.define_dec("SYS_GETINFO_NAME_LEN", callnr::SYS_GETINFO_NAME_LEN as i64);
157	    f.define_dec("EXEC_NAME_LEN", callnr::EXEC_NAME_LEN as i64);
158	    f.define_dec("PRIVCTL_SET_USER", callnr::PRIVCTL_SET_USER.into());
159	    f.define_dec("SCHEDCTL_FLAG_KERNEL", callnr::SCHEDCTL_FLAG_KERNEL.into());
160	
161	    f.section("SYS_DIAGCTL subcodes + inline-text payload");
162	    f.define_dec("DIAGCTL_CODE_DIAG", callnr::DIAGCTL_CODE_DIAG.into());
163	    f.define_dec(
164	        "DIAGCTL_CODE_STACKTRACE",
165	        callnr::DIAGCTL_CODE_STACKTRACE.into(),
166	    );
167	    f.define_dec(
168	        "DIAGCTL_CODE_REGISTER",
169	        callnr::DIAGCTL_CODE_REGISTER.into(),
170	    );
171	    f.define_dec(
172	        "DIAGCTL_CODE_UNREGISTER",
173	        callnr::DIAGCTL_CODE_UNREGISTER.into(),
174	    );
175	    f.define_dec("DIAG_TEXT_OFF", callnr::DIAG_TEXT_OFF as i64);
176	    f.define_dec("DIAG_TEXT_MAX", callnr::DIAG_TEXT_MAX as i64);
177	
178	    f.section("SYS_VMCTL subcalls");
179	    f.define_dec("VMCTL_PT_MAP", callnr::VMCTL_PT_MAP.into());
180	    f.define_dec("VMCTL_PT_UNMAP", callnr::VMCTL_PT_UNMAP.into());
181	    f.define_dec(
182	        "VMCTL_CLEAR_PAGEFAULT",
183	        callnr::VMCTL_CLEAR_PAGEFAULT.into(),
184	    );
185	    f.define_dec("VMCTL_GET_PAGEFAULT", callnr::VMCTL_GET_PAGEFAULT.into());
186	    f.define_dec("VMCTL_VMINHIBIT_SET", callnr::VMCTL_VMINHIBIT_SET.into());
187	    f.define_dec(
188	        "VMCTL_VMINHIBIT_CLEAR",
189	        callnr::VMCTL_VMINHIBIT_CLEAR.into(),
190	    );
191	    f.define_dec("NR_VMCTL_SUBCALLS", callnr::NR_VMCTL_SUBCALLS as i64);
192	    f.blank();
193	    f.define_dec("VMCTL_PROT_WRITE", callnr::VMCTL_PROT_WRITE.into());
194	    f.define_dec("VMCTL_PROT_EXEC", callnr::VMCTL_PROT_EXEC.into());
195	
196	    for band in bands() {
197	        f.section(band.title);
198	        f.define_hex(band.base_name, band.base.into());
199	        for (name, value) in &band.members {
200	            f.define_hex(name, (*value).into());
201	        }
202	        if let Some((count_name, count)) = band.count {
203	            f.define_dec(count_name, count as i64);
204	        }
205	    }
206	
207	    f.section("band ordering");
208	    f.block_comment(&[
209	        "Mirrors the `const _: () = assert!(..)` guards in callnr.rs: every band",
210	        "sits above the previous one and entirely below NOTIFY_MESSAGE, so no",
211	        "server request can ever be mistaken for a kernel NOTIFY.",
212	    ]);
213	    f.static_assert(
214	        "NR_SYS_CALLS >= NR_KERN_CALLS",
215	        "the privilege call mask is narrower than the kernel-call set",
216	    );
217	    f.static_assert(
218	        "PM_RQ_BASE > KERNEL_CALL + NR_KERN_CALLS - 1",
219	        "the PM band overlaps the kernel calls",
220	    );
221	    f.static_assert(
222	        "PM_RQ_BASE + NR_PM_MSGS - 1 < VM_RQ_BASE",
223	        "the PM band overlaps the VM band",
224	    );
225	    f.static_assert("SEF_RQ_BASE > VM_FORK", "the SEF band overlaps the VM band");
226	    f.static_assert(
227	        "DS_RQ_BASE > SEF_RQ_BASE + NR_SEF_MSGS - 1",
228	        "the DS band overlaps the SEF band",
229	    );
230	    f.static_assert(
231	        "SCHED_RQ_BASE > DS_RQ_BASE + NR_DS_REQUESTS - 1",
232	        "the SCHED band overlaps the DS band",
233	    );
234	    f.static_assert(
235	        "SCHED_RQ_BASE + NR_SCHED_MSGS - 1 < NOTIFY_MESSAGE",
236	        "a server request number collides with NOTIFY_MESSAGE",
237	    );
238	
239	    f.guard_close(GUARD);
240	    f.finish()
241	}
