243	#[cfg(test)]
244	mod tests {
245	    use super::*;
246	    use crate::builder;
247	
248	    #[test]
249	    fn kernel_calls_render_from_live_constants() {
250	        let text = render();
251	        for (name, value) in kernel_calls() {
252	            assert_eq!(
253	                builder::define_value(&text, name).as_deref(),
254	                Some(format!("0x{value:X}").as_str()),
255	                "{name} did not render from its Rust constant"
256	            );
257	        }
258	    }
259	
260	    #[test]
261	    fn the_kernel_call_list_is_complete_and_contiguous() {
262	        let calls = kernel_calls();
263	        assert_eq!(calls.len(), callnr::NR_KERN_CALLS);
264	        for (i, (name, value)) in calls.into_iter().enumerate() {
265	            assert_eq!(
266	                value,
267	                callnr::KERNEL_CALL + i as i32,
268	                "{name} is out of order"
269	            );
270	        }
271	    }
272	
273	    #[test]
274	    fn every_band_base_member_and_count_appears() {
275	        let text = render();
276	        for band in bands() {
277	            assert_eq!(
278	                builder::define_value(&text, band.base_name).as_deref(),
279	                Some(format!("0x{:X}", band.base).as_str())
280	            );
281	            for (name, value) in &band.members {
282	                assert_eq!(
283	                    builder::define_value(&text, name).as_deref(),
284	                    Some(format!("0x{value:X}").as_str()),
285	                    "{name} missing from the {} band",
286	                    band.title
287	                );
288	            }
289	            if let Some((count_name, count)) = band.count {
290	                assert_eq!(
291	                    builder::define_value(&text, count_name).as_deref(),
292	                    Some(count.to_string().as_str())
293	                );
294	            }
295	        }
296	    }
297	
298	    /// The completeness half of the band lock: `every_band_base_member_and_count_appears`
299	    /// only proves that whatever is listed renders, so on its own a new request
300	    /// that bumped `NR_PM_MSGS` would grow the C count and the ordering asserts
301	    /// while silently omitting its own macro. Each band's members must therefore
302	    /// be exactly `count` entries, contiguous from `base`.
303	    #[test]
304	    fn every_band_member_list_matches_its_count() {
305	        for band in bands() {
306	            if let Some((count_name, count)) = band.count {
307	                assert_eq!(
308	                    band.members.len(),
309	                    count,
310	                    "the {} band lists {} members but {count_name} is {count}",
311	                    band.title,
312	                    band.members.len()
313	                );
314	            }
315	            for (i, (name, value)) in band.members.iter().enumerate() {
316	                assert_eq!(
317	                    *value,
318	                    band.base + i as i32,
319	                    "{name} is out of order in the {} band",
320	                    band.title
321	                );
322	            }
323	        }
324	    }
325	
326	    /// VM is the one band with no `NR_*` count on the Rust side, so its guard
327	    /// names the last member instead. Pin both the guard text and the member the
328	    /// guard names, so a future `NR_VM_MSGS` — or a `VM_RQ_BASE + 5` request —
329	    /// is a deliberate change here rather than a silent gap.
330	    #[test]
331	    fn the_vm_band_has_no_count_constant() {
332	        let vm = bands()
333	            .into_iter()
334	            .find(|b| b.base_name == "VM_RQ_BASE")
335	            .unwrap();
336	        assert!(vm.count.is_none());
337	        assert_eq!(
338	            vm.members.last().map(|(name, value)| (*name, *value)),
339	            Some(("VM_FORK", callnr::VM_FORK)),
340	            "the SEF ordering assert names the VM band's last member"
341	        );
342	        assert!(render().contains("SEF_RQ_BASE > VM_FORK"));
343	    }
344	
345	    /// The C name and the Rust name must stay identical. The Rust constant was
346	    /// `NR_KERN_CALLS_PHASE4` until slice 5.1, which renamed it to match this
347	    /// header rather than let a phase-scoped name outlive Phase 4 and cross the
348	    /// slice-5.6 ABI freeze. Nothing may reintroduce a phase suffix on either
349	    /// side.
350	    #[test]
351	    fn nr_kern_calls_is_not_phase_suffixed() {
352	        let text = render();
353	        assert_eq!(
354	            builder::define_value(&text, "NR_KERN_CALLS").as_deref(),
355	            Some(callnr::NR_KERN_CALLS.to_string().as_str())
356	        );
357	        assert!(
358	            !text.contains("PHASE"),
359	            "the ABI header must carry no phase-scoped names"
360	        );
361	    }
362	}
