95	/// `UnsafeCell`-wrapped static registry. See the module note for the
96	/// single-mutator invariant that makes the `Sync` impl sound.
97	#[repr(transparent)]
98	struct Registry(UnsafeCell<[Entry; CAP]>);
99	
100	// SAFETY: DS is a single-threaded EL0 process with no interrupt handlers of its
101	// own; the table is only ever accessed from DS's straight-line receive loop, so
102	// there is never concurrent access.
103	unsafe impl Sync for Registry {}
104	
105	static TABLE: Registry = Registry(UnsafeCell::new([Entry::EMPTY; CAP]));
106	
107	/// Publish `ep` under `key` in the global registry. Returns `OK` / `EINVAL` /
108	/// `ENOMEM` (see [`publish_in`]).
109	pub fn publish(key: &[u8; KEY_LEN], ep: i32) -> i32 {
110	    // SAFETY: single-mutator invariant (module note); no other reference into
111	    // the table is live during DS's straight-line loop.
112	    let t = unsafe { &mut *TABLE.0.get() };
113	    publish_in(t, key, ep)
114	}
115	
116	/// Look up the endpoint registered under `key` in the global registry.
117	pub fn retrieve(key: &[u8; KEY_LEN]) -> Option<i32> {
118	    // SAFETY: single-mutator invariant (module note); shared read, no live `&mut`.
119	    let t = unsafe { &*TABLE.0.get() };
120	    retrieve_in(t, key)
121	}
122	
123	/// True if `key` is registered in the global registry.
124	pub fn check(key: &[u8; KEY_LEN]) -> bool {
125	    // SAFETY: single-mutator invariant (module note); shared read, no live `&mut`.
126	    let t = unsafe { &*TABLE.0.get() };
127	    check_in(t, key)
128	}
