41	/// User-page permission. Maps onto the aarch64 stage-1 descriptor's AP +
42	/// PXN + UXN bits; kernel callers describe intent here and `prot_attrs()`
43	/// converts to the bit pattern.
44	#[derive(Copy, Clone, Debug)]
45	pub struct Prot {
46	    /// EL0 may write.
47	    pub writable: bool,
48	    /// EL0 may fetch from this page (code).
49	    pub executable: bool,
50	}
51	
52	impl Prot {
53	    pub const RO_CODE: Self = Self {
54	        writable: false,
55	        executable: true,
56	    };
57	    pub const RW_DATA: Self = Self {
58	        writable: true,
59	        executable: false,
60	    };
61	    pub const RO_DATA: Self = Self {
62	        writable: false,
63	        executable: false,
64	    };
65	}
