67	fn prot_attrs(prot: Prot) -> u64 {
68	    let ap = if prot.writable {
69	        PTE_AP_RW_EL0
70	    } else {
71	        PTE_AP_RO_EL0
72	    };
73	    let uxn = if prot.executable { 0 } else { PTE_UXN };
74	    PTE_AF | PTE_SH_INNER | ap | PTE_PXN | uxn | pte_attr_idx(ATTR_IDX_NORMAL)
75	}
