3	//! User-memory IPC message copies.
4	//!
5	//! Each `mini_send` / `mini_receive` handler accepts a user-supplied VA in
6	//! `frame.x[2]`. The kernel reads the outgoing [`Message`] out of that buffer
7	//! when the caller blocks, and writes the incoming `Message` back to that
8	//! buffer when the kernel resumes the caller (the `MF_DELIVERMSG` flush).
9	//!
10	//! Both directions go through [`crate::mm::uaccess`], which walks the owning
11	//! process's page tables and copies via the frame's HHDM alias. Two
12	//! consequences, per decision D5:
13	//!
14	//! - A user pointer that is *in range but unmapped* yields [`EFAULT`], not an
15	//!   EL1 data abort. Before slice 5.1 this was a raw `read_volatile` /
16	//!   `write_volatile` through the live TTBR0, and a bad pointer panicked the
17	//!   kernel — the same-EL vector has no fixup path.
18	//! - The copy does not depend on which address space is active, so the
19	//!   deferred flush can write a receiver's buffer before its TTBR0 is
20	//!   installed. (`sched::schedule_next` still installs it first, but only
21	//!   because `eret` needs it — the flush no longer cares.)
22	//!
23	//! [`user_va_ok`] stays in front as the cheap range/alignment pre-gate: it is
24	//! what rejects NULL and misaligned pointers before any table walk happens.
25	//!
26	//! This module holds no `unsafe`. Messages are staged through a plain
27	//! `[u8; 104]` and reassembled field-by-field, so every raw-pointer operation
28	//! in the user-copy path lives in exactly one place, `mm::uaccess`.
29	
30	use minixrs_kernel_shared::error::EFAULT;
31	use minixrs_kernel_shared::message::{Message, user_va_ok};
32	
33	use crate::mm::uaccess;
34	
35	/// Wire size of a [`Message`]: 104 bytes, `m_source` / `m_type` / `payload`
36	/// at offsets 0 / 4 / 8.
37	const MSG_BYTES: usize = core::mem::size_of::<Message>();
38	const M_TYPE_OFF: usize = 4;
39	const PAYLOAD_OFF: usize = 8;
40	const PAYLOAD_BYTES: usize = MSG_BYTES - PAYLOAD_OFF;
41	
42	// Tie the offsets to the actual struct layout. Without this, adding a field
43	// ahead of `payload` would leave `PAYLOAD_OFF = 8` reading the wrong 96 bytes
44	// — a *silent* miscopy, since the slice length would still be right and the
45	// `try_into`s below would still succeed. The `try_into().expect(...)` calls are
46	// unreachable by construction (constant ranges within a constant-size array);
47	// these asserts are what actually makes a layout change a compile error.
48	const _: () = assert!(M_TYPE_OFF == core::mem::offset_of!(Message, m_type));
49	const _: () = assert!(PAYLOAD_OFF == core::mem::offset_of!(Message, payload));
50	const _: () = assert!(core::mem::offset_of!(Message, m_source) == 0);
51	const _: () = assert!(PAYLOAD_BYTES == 96);
52	
53	/// Copy a [`Message`] out of user memory at `va` in the address space rooted
54	/// at `ttbr0_pa`.
55	///
56	/// Returns `Err(EFAULT)` if `va` fails the range/alignment gate or any page of
57	/// the buffer is unmapped in that address space.
58	pub(crate) fn copy_msg_from_user(ttbr0_pa: u64, va: u64) -> Result<Message, i32> {
59	    if !user_va_ok(va, MSG_BYTES) {
60	        return Err(EFAULT);
61	    }
62	    let mut buf = [0u8; MSG_BYTES];
63	    uaccess::copy_from_user_as(ttbr0_pa, va, &mut buf)?;
64	    Ok(Message {
65	        m_source: i32::from_ne_bytes([buf[0], buf[1], buf[2], buf[3]]),
66	        m_type: i32::from_ne_bytes([
67	            buf[M_TYPE_OFF],
68	            buf[M_TYPE_OFF + 1],
69	            buf[M_TYPE_OFF + 2],
70	            buf[M_TYPE_OFF + 3],
71	        ]),
72	        payload: core::array::from_fn(|i| buf[PAYLOAD_OFF + i]),
73	    })
74	}
75	
76	/// Write a [`Message`] into user memory at `va` in the address space rooted at
77	/// `ttbr0_pa`.
78	///
79	/// Returns `Err(EFAULT)` if `va` fails the range/alignment gate, or any page of
80	/// the buffer is unmapped or not EL0-writable. All-or-nothing: on error the
81	/// user's buffer is untouched.
82	pub(crate) fn copy_msg_to_user(ttbr0_pa: u64, va: u64, m: &Message) -> Result<(), i32> {
83	    if !user_va_ok(va, MSG_BYTES) {
84	        return Err(EFAULT);
85	    }
86	    let mut buf = [0u8; MSG_BYTES];
87	    buf[0..M_TYPE_OFF].copy_from_slice(&m.m_source.to_ne_bytes());
88	    buf[M_TYPE_OFF..PAYLOAD_OFF].copy_from_slice(&m.m_type.to_ne_bytes());
89	    buf[PAYLOAD_OFF..PAYLOAD_OFF + PAYLOAD_BYTES].copy_from_slice(&m.payload);
90	    uaccess::copy_to_user_as(ttbr0_pa, va, &buf)
91	}
