    let put = |w: &mut [u8; GRANT_ENTRY_SIZE], off: usize, bytes: &[u8]| {
        w[off..off + bytes.len()].copy_from_slice(bytes);
    };
    put(
        &mut want,
        core::mem::offset_of!(GrantEntry, flags),
        &e.flags.to_ne_bytes(),
